const e=[{id:1,code:"MIL-101",icon:"Siren",accent:"#dc2626",title:"بەرسڤدانا بلەز",subtitle:"Rapid Emergency Response",summary:"ڕێکارێن بەرسڤدانا بلەز ل دەمێ ڕووداوێن تەنگاڤیێ",blocks:[{body:"ل دۆخێن سەربازی، لەزا بەرسڤدانێ ژیانێ دپارێزیت. ئامادەباشی و ڕاهێنانا بەردەوام پێدڤینە."},{heading:"١. هەلسەنگاندنا دۆخی (SALUTE)",body:"ڕاپۆرتا بلەز:",points:["S - Size: ژمارە و قەبارە.","A - Activity: چ دکەن.","L - Location: جه (کۆئۆردینات).","U - Unit: ئێکە یان جۆر.","T - Time: دەم.","E - Equipment: کەرەستە و ئامێر."]},{heading:"٢. بەرسڤدانا ئاگری",body:"ل بنکەیا سەربازی:",points:["ئاگەهدارکرن: سیرێن یان هاوار، و ئێکسەر گازی ١١٥ بکە.","تیمێ ڤەمراندنا ئاگری: ب لەز، تەنێ بۆ ئاگرێ بچویک و دوور ژ تەقەمەنیێ.","دەرکەفتن: ب ڕێکوپێکی.","کۆمبوون: ل خالا کۆمبوونێ یا دیارکری، ل سەرێ بای و دەرڤەی ناڤچا مەترسیێ.","سەرژمێری: هەمی کەس بهێنە هژمارتن."]},{heading:"٣. هەوارهاتنا میدانی",body:"هەوارهاتنا ئێکێ ل میدانێ:",points:["خوینبەربوونا مەترسیدار ژ دەست یان لنگی: ئێکسەر تۆرنیکێتێ ببەستە، و دەمێ گرێدانێ بنڤیسە.","شکەستن: ئەندامی جێگیر بکە و نەلڤینە.","سۆتن: ٢٠ خولەکان ب ئاڤا ڕەوان یا فێنک سار بکە.","فشارا سنگی (CPR): ٣٠:٢ (ئەگەر ڕاهێنان نەدیتبی، تەنێ فشارێن سنگی)، و گازی ١٢٢ بکە."]}],media:[{kind:"video",src:"media/videos/mil_response.mp4",title:"بەرسڤدانا بلەز",description:"ڕێکارێن سەرەکی"}],quiz:[{question:"د SALUTE دا، پیتا L چ واتایێ ددەت؟",options:[{text:"ڕووناهی",correct:!1},{text:"جه",correct:!0},{text:"درێژی",correct:!1},{text:"لیست",correct:!1}],explanation:"L = Location: جه و کۆئۆردینات."},{question:"ل بنکەیا سەربازی، تیمێ ڤەمراندنا ئاگری دشێت کیش ئاگران ڤەمرینیت؟",options:[{text:"هەر ئاگرەک، ب مەرجەکێ تیم ب لەز بگەهیت",correct:!1},{text:"ئاگرێ ل تەنیشت تەقەمەنیێ، دا کو تەقەمەنی بهێتە پاراستن",correct:!1},{text:"هەر ئاگرەک، ب مەرجەکێ تەمرینکێن بەس هەبن",correct:!1},{text:"تەنێ ئاگرێ بچویک یێ دوور ژ تەقەمەنیێ",correct:!0}],explanation:"ئەڤ وانە تیمێ ڤەمراندنا ئاگری تەنێ بۆ ئاگرێ بچویک و دوور ژ تەقەمەنیێ دیار دکەت؛ ئێکسەر ئاگەهدار بکە و گازی ١١٥ بکە."},{question:"سەربازەک خوینبەربوونا مەترسیدار ژ لنگی هەیە. ئەڤ وانە دبێژیت چ بکەی؟",options:[{text:"ئێکسەر تۆرنیکێتێ ببەستە و دەمێ گرێدانێ بنڤیسە",correct:!0},{text:"لنگی بلند بکە و چاڤەڕێ بە کا خوین ب خوە ڕادوەستیت",correct:!1},{text:"تۆرنیکێتێ ببەستە و هەر چەند خولەکان شل بکە دا کو خوین بچیت",correct:!1},{text:"برینێ ب ئاڤێ بشۆ و بێ داپۆشین بهێلە دا کو هشک ببیت",correct:!1}],explanation:"بۆ خوینبەربوونا مەترسیدار ژ دەست یان لنگی، وانە دبێژیت: ئێکسەر تۆرنیکێتێ ببەستە و دەمێ گرێدانێ بنڤیسە."}]},{id:2,code:"MIL-102",icon:"Tent",accent:"#16a34a",title:"دامەزراندنا کامپی",subtitle:"Safe Camp Setup",summary:"دامەزراندنا کامپەکێ سەربازی ب سەلامەتی",blocks:[{body:"کامپێ سەربازی دڤێت ژ مەترسیێن سروشتی و یێن دەستکردێ مرۆڤی پاراستی بیت."},{heading:"١. هەلبژارتنا جهی",body:"جهێ گونجای:",points:["جهێ بلند: نە ل نهال و گەلیان (مەترسیا لەهیێ).","نێزیکی ئاڤێ، بەلێ نە گەلەک نێزیک.","پاراستی ژ بای، بەلێ نە ل بن دارێن مەزن (چق و برووسک).","ڕێکا هاتن و دەرکەفتنێ: ئاشکرا و ڤەکری."]},{heading:"٢. ڕێکخستنا کامپی",body:"جهێن سەرەکی:",points:["چادر: ڕیز ب ڕیز، ب ماوە د ناڤبەرا واندا.","جهێ ئاگری: دوور ژ چادران.","دەستاڤ (تەوالێت): دوور ژ ئاڤێ و خوارنێ، و ل خوارێ بای.","خالا هەوارهاتنا ئێکێ: ل ناڤەڕاستا کامپی."]},{heading:"٣. سەلامەتیا کامپی",body:"ڕێسایێن گرنگ:",points:["ئاگر: چاودێریا بەردەوام (٢٤ دەمژمێر).","کارەبا: جەنەراتۆر دوور ژ چادران بیت (مەترسیا غازا CO).","سۆتەمەنی: ل جهەکێ تایبەت و دوور.","تەمرینک: نێزیکی چادران و جهێن ئاگری."]}],media:[{kind:"image",src:"media/images/mil_camp.png",title:"کامپ",description:"ڕێکخستن"}],quiz:[{question:"جهێ ئاگری دڤێت ل کیڤە بیت؟",options:[{text:"نێزیکی چادران",correct:!1},{text:"دوور ژ چادران",correct:!0},{text:"د ناڤ چادرێ دا",correct:!1},{text:"هەر جهەکێ کامپی بیت",correct:!1}],explanation:"دوور ژ چادران، دا کو ئاگر بەلاڤی چادران نەبیت."},{question:"بۆچی دڤێت کامپ ل جهێ بلند بهێتە دامەزراندن و نە ل نهال و گەلیان؟",options:[{text:"چونکی جهێ بلند باشتر ژ بای پاراستییە",correct:!1},{text:"ژبەر مەترسیا لەهیێ",correct:!0},{text:"چونکی نێزیکی دارێن مەزن بۆ سێبەرێ یە",correct:!1},{text:"چونکی گەلی گەلەک ژ ئاڤێ دوورن",correct:!1}],explanation:"وانە جهێ بلند هەلدبژێریت و نە نهال و گەلیان، ژبەر مەترسیا لەهیێ."},{question:"جەنەراتۆر دڤێت ل کامپی ل کیڤە بن، و بۆچی؟",options:[{text:"د ناڤ چادرەکێ دا، دا کو ژ باران و تۆزێ بهێنە پاراستن",correct:!1},{text:"ل تەنیشت جهێ سۆتەمەنیێ، دا کو تژیکرن ب لەز بیت",correct:!1},{text:"دوور ژ چادران، ژبەر مەترسیا غازا CO",correct:!0},{text:"ل ناڤەڕاستا کامپی، ل تەنیشت خالا هەوارهاتنا ئێکێ",correct:!1}],explanation:"جەنەراتۆر دڤێت دوور ژ چادران بن ژبەر مەترسیا غازا CO؛ سۆتەمەنی ل جهەکێ تایبەت و دوور دهێتە دانان."}]},{id:3,code:"MIL-103",icon:"HeartPulse",accent:"#dc2626",title:"هەوارهاتنا میدانی (MARCH)",subtitle:"Tactical First Aid",summary:"هەوارهاتنا ئێکێ ل دۆخێن میدانی — ڕێزبەندیا MARCH",blocks:[{body:"هەوارهاتنا میدانی ژ هەوارهاتنا ئاسایی جودایە: لەز و ڕێزبەندیا کاران گرنگترن. ڕێزبەندیا MARCH ژ پرۆتۆکۆلا چاودێریا تاکتیکی یا برینداران (TCCC) ژیانێ دپارێزیت."},{heading:"١. ڕێزبەندیا MARCH",body:"ڕێزبەندیا کارێن هەوارهاتنێ:",points:["M - Massive Hemorrhage: خوینبەربوونا مەترسیدار ئێکەمە: فشارا ڕاستەوخۆ، پڕکرنا برینێ، تۆرنیکێت.","A - Airway: ڕێکا هەناسێ ڤەکە.","R - Respiration: هەناسەدانێ و برینێن سنگی بپشکنە.","C - Circulation: سووڕانا خوینێ و نیشانێن شۆکێ.","H - Hypothermia / Head Injury: بریندارێ گەرم بهێلە و برینێن سەری بپشکنە."]},{heading:"٢. تۆرنیکێت (Tourniquet)",body:"بۆ خوینبەربوونا مەترسیدار ژ دەست یان لنگی:",points:["جه: ٥-٧ سم سەرتر ژ برینێ، نە ل سەر جومگەهێ.","توندکرن: دارێ بزڤڕینە هەتا خوین ڕادوەستیت.","دەم: دەمێ گرێدانێ ل سەر تۆرنیکێتێ یان ل سەر ئەنیا بریندار بنڤیسە.","چ جاران ل میدانێ شل نەکە؛ تەنێ تیمێ پزیشکی ل نەخۆشخانێ دشێت لابەت.","بریندارێ ب لەز ڤەگوهێزە (MEDEVAC) و دەمێ گرێدانێ بێژە تیمێ پزیشکی."]},{heading:"٣. ڕەوشا ڕزگاری (Recovery Position)",body:"بۆ کەسێ بێهش کو ب ئاسایی هەناسێ ددەت، ئەگەر گومانا برینا ستوی، پشتێ، کەماخێ یان هەستیێ حەوزێ نەبیت:",points:["١. بریندارێ ل سەر لایێ وی بزڤڕینە.","٢. دەستێ وی یێ ژۆری بدە بن ڕوومەتا وی.","٣. چۆکا لنگێ ژۆری بچەمینە دا ل سەر زکی نەزڤڕیت.","٤. سەری پچەکێ پاشڤە ببە دا ڕێکا هەناسێ ڤەکری بمینیت.","٥. هەناسێ بەردەوام بپشکنە هەتا هاریکاری دگەهیت (١٢٢ یان MEDEVAC)."]},{heading:"٤. سۆتن",body:"چارەسەریا سۆتنێ ل میدانێ:",points:["سارکرن: ٢٠ خولەکان ب ئاڤا پاقژ و فێنک یا ڕەوان.","داپۆشین: گازێ ستێریل یان نایلۆنا پاقژ، بێ پێچانا توند.","قەشا بکار نەئینە!","کرێم، دۆهن و مەعجوونا ددانان بکار نەئینە؛ بلقان نەتەقینە.","سۆتنا مەزن یان ل ڕوو، دەست و جومگەهان: ب لەز ڤەگوهێزە (١٢٢ یان MEDEVAC)."]}],media:[{kind:"video",src:"media/videos/mil_tourniquet.mp4",title:"تۆرنیکێت",description:"چەوانیا بکارئینانێ"},{kind:"image",src:"media/images/mil_recovery.png",title:"ڕەوشا ڕزگاری",description:"بۆ بریندارێ بێ هش یێ کو هەناسێ ددەت"}],quiz:[{question:"د ڕێزبەندیا MARCH دا، چ ئێکەمە؟",options:[{text:"هەناسەدان و برینێن سنگی",correct:!1},{text:"خوینبەربوونا مەترسیدار",correct:!0},{text:"سووڕانا خوینێ و نیشانێن شۆکێ",correct:!1},{text:"سەرما",correct:!1}],explanation:"M ئێکەمە، چونکی ل میدانێ خوینبەربوون مەزنترین ئەگەرێ وێ مرنێ یە یا کو دشێت ڕێ لێ بهێتە گرتن."},{question:"تۆرنیکێت کەنگی بکار دئینین؟",options:[{text:"بۆ هەمی برینان، دا هەر خوینبەربوونەکێ ڕاوەستینیت",correct:!1},{text:"خوینبەربوونا مەترسیدار ژ دەست یان لنگی",correct:!0},{text:"خوینبەربوون ژ برینەکا مەزن ل سەری یان ستۆیێ",correct:!1},{text:"خوینبەربوون ژ برینەکا زکی یان سنگی",correct:!1}],explanation:"تەنێ بۆ خوینبەربوونا مەترسیدار ژ دەست و لنگان؛ دەمێ گرێدانێ بنڤیسە و چ جاران ل میدانێ شل نەکە."},{question:"تۆرنیکێت ل کیڤە دهێتە بەستن؟",options:[{text:"ڕاستەوخۆ ل سەر برینێ، دا کو فشارێ ل سەر دەمارا خوینێ بکەت",correct:!1},{text:"ل سەر نێزیکترین جومگەهێ، چونکی ل وێرێ باشتر دگریت",correct:!1},{text:"ژێرتر ژ برینێ، د ناڤبەرا برینێ و دەست یان پێی دا",correct:!1},{text:"٥-٧ سم سەرتر ژ برینێ، نە ل سەر جومگەهێ",correct:!0}],explanation:"وانە تۆرنیکێتێ ٥-٧ سم سەرتر ژ برینێ دادنیت، نە ل سەر جومگەهێ؛ دەمێ گرێدانێ ل سەر تۆرنیکێتێ یان ل سەر ئەنیا بریندار بنڤیسە."}]},{id:4,code:"MIL-104",icon:"Radio",accent:"#2563eb",title:"پەیوەندیا تەنگاڤیێ",subtitle:"Emergency Communications",summary:"سیستەمێن پەیوەندیکرنێ ل دەمێ تەنگاڤیێ",blocks:[{body:"پەیوەندیا باش کلیلا سەرکەفتنێ یە. د کارەساتان دا، دبیت تۆڕێن پەیوەندیێ ڕاوەستن."},{heading:"١. سیستەمێن پەیوەندیێ",body:"جۆرێن پەیوەندیکرنێ:",points:["ڕادیۆ: ئامرازێ سەرەکی، هەمیشە ئامادە.","مۆبایل: ئەگەر تۆڕ هەبیت.","ساتەلایت: بۆ جهێن دوور.","ڕووناهی: ئاماژێن دیتنێ.","دەنگ: سیرێن، فیکە، هاوار."]},{heading:"٢. پەیاما دروست",body:"چەوا پەیامێ بدەی:",points:["جه: کۆئۆردیناتێن دروست.","دۆخ: چ ڕوویدا.","ژمارە: چەند کەس و چەند بریندار.","پێدڤی: چ پێدڤییە.","دووبارەکرن: بۆ پشتڕاستبوونێ."]},{heading:"٣. کۆدێن تەنگاڤیێ",body:"نموونەیێن کۆدێن ڕەنگی (کۆد ل دەزگەهەکێ بۆ یێ دی جودا دبن؛ ل دویڤ ڕێنمایێن فەرماندەیا خوە بچە):",points:["کۆدێ سۆر: ئاگر.","کۆدێ شین: تەنگاڤیا پزیشکی.","کۆدێ ڕەش: گەفا تەقەمەنیێ.","کۆدێ زەرد: ئاگەهداری و ئامادەباشی.","کۆدێ کەسک: سەلامەتی، دۆخ ب دویماهی هات."]}],media:[{kind:"video",src:"media/videos/mil_radio.mp4",title:"ڕادیۆ",description:"بکارئینان"}],quiz:[{question:"کۆدێ سۆر چ واتایێ ددەت؟",options:[{text:"سەلامەتی",correct:!1},{text:"تەنگاڤیا پزیشکی",correct:!1},{text:"ئاگر",correct:!0},{text:"ئاگەهداری",correct:!1}],explanation:"کۆدێ سۆر = ئاگرکەفتن."},{question:"پەیاما دروست یا تەنگاڤیێ دڤێت چ تێدا هەبیت؟",options:[{text:"جه، دۆخ، ژمارا کەس و برینداران و پێدڤی",correct:!0},{text:"تەنێ ناڤێ تە و ئێکەیا تە، دا کو بنکە گازی تە بکەت",correct:!1},{text:"دۆخ و داخوازا هاریکاریێ؛ جه دشێت پاشی بهێت",correct:!1},{text:"پلەیا تە، دەم و کەش و هەوایێ جهی",correct:!1}],explanation:"پەیاما دروست کۆئۆردیناتێن دروست یێن جهی، چ ڕوویدا، چەند کەس و چەند بریندار، و چ پێدڤییە دیار دکەت، و بۆ پشتڕاستبوونێ دهێتە دووبارەکرن."},{question:"بۆچی دڤێت ل دویڤ ڕێنمایێن فەرماندەیا خوە بچی بۆ کۆدێن ڕەنگی یێن تەنگاڤیێ؟",options:[{text:"چونکی ڕەنگ ب یاسایا نێڤدەولەتی بۆ هەمی هێزان هاتینە دیارکرن",correct:!1},{text:"چونکی کۆد ل دەزگەهەکێ بۆ یێ دی جودا دبن",correct:!0},{text:"چونکی تەنێ فەرماندە دشێن کۆدان ب دەنگێ بلند بێژن",correct:!1},{text:"چونکی کۆد بۆ ئاسایشێ هەر ڕۆژ دهێنە گوهۆڕین",correct:!1}],explanation:"کۆد ل دەزگەهەکێ بۆ یێ دی جودا دبن، ژبەرهندێ ڕەنگێن ڤێ وانێ تەنێ نموونەنە؛ ل دویڤ ڕێنمایێن فەرماندەیا خوە بچە."}]},{id:5,code:"MIL-105",icon:"Biohazard",accent:"#ca8a04",title:"پاراستن ژ مەترسیێن CBRN",subtitle:"Chemical, Biological, Radiological, Nuclear",summary:"پاراستن ژ مەترسیێن کیمیایی، بایۆلۆژی، تیشکی و ئەتۆمی",blocks:[{body:"مەترسیێن کیمیایی، بایۆلۆژی، تیشکی و ئەتۆمی (CBRN) گەفەکا ڕاستەقینەنە بۆ هێزێن سەربازی و شارستانیان. دڤێت پێشمەرگە ڤان مەترسیان بناسن و بزانن چەوا خوە ژێ بپارێزن."},{heading:"١. مەترسیا کیمیایی (C)",body:"ماددەیێن کیمیایی:",points:["ماددەیێن دەماری (Nerve Agents، وەک Sarin و VX): کوژەکترینن.","ماددەیێن خەندقێنەر (Choking Agents، وەک Chlorine و Phosgene): زیانێ دگەهیننە سییان.","ماددەیێن بلقکەر (Blister Agents، وەک Mustard): پێست، چاڤ و سییان دسۆژن.","غازا فرمێسکان (CS): د ڕاهێنانێ دا بۆ تاقیکرنا ماسکێ دهێتە بکارئینان.","نیشانە: فرمێسک، ئاڤا دفنێ، تەنگیا سنگی، کۆخک، بێهنەکا نەئاسایی.","کار: ئێکسەر ماسکێ بکە، ئاگەهدار بکە، و ژ ناڤچێ دەرکەڤە بەرەڤ سەرێ بای (ئالیێ بای ژێ دهێت) و جهێن بلند."]},{heading:"٢. مەترسیا بایۆلۆژی (B)",body:"ماددەیێن بایۆلۆژی:",points:["ئەنسراکس (Anthrax): بەکتریایە، دبیت وەک تۆزەکا سپی بیت.","تاعوون (Plague): بەکتریایە، جۆرێ سییان ب ڕێکا هەوایێ ژ مرۆڤی بۆ مرۆڤی دگوهێزیت.","ئاولە (Smallpox): ڤایرۆسە، ب لەز بەلاڤ دبیت.","نیشانە: تا، کۆخک، لاوازی — پشتی چەند ڕۆژان یان هەفتیان دیار دبن.","پاراستن: ماسک، دەستکێش، دووربوون ژ نەخۆشان، و چاودێریا ساخلەمیێ.","چارەسەری: ئانتیبایۆتیک یان ڤاکسین، ل دویڤ بڕیارا پزیشکی."]},{heading:"٣. تیشکی (R) و ئەتۆمی (N)",body:"مەترسیا تیشکێن ڕادیۆئاکتیڤ:",points:["بۆمبا پیس (Dirty Bomb): تەقەمەنی + ماددەیەکا تیشکدەر.","ئەتۆمی: تەقینا چەکێ ئەتۆمی.","پاراستن: دەم + دووراهی + ڕێگر (Time, Distance, Shielding).","ڕێگر: دیوارێن ستویر، بێتۆن، ئاخ.","پاقژکرن (Decontamination): جلکێن دەرڤە بکە دەر و لەشی ب ئاڤ و سابوونێ بشۆ.","دەم: هەتا کێمتر ل نێزیک بی، باشترە."]},{heading:"٤. کەرەستێن پاراستنێ (PPE)",body:"ئاستێن MOPP (Mission Oriented Protective Posture) — هەر ئاستەک کەرەستەکێ ل سەر ئاستێ بەری خوە زێدە دکەت:",points:["ماسکا غازێ ب فلتەرێ CBRN، و جلک، پوتین و دەستکێشێن پاراستنێ هەمیشە ل بەردەست بن.","MOPP 1: جلکێن پاراستنێ (Overgarment) دهێنە کرن.","MOPP 2: MOPP 1 + پوتینێن پاراستنێ (Overboots).","MOPP 3: MOPP 2 + ماسکا غازێ و کلاوێ وێ (Hood).","MOPP 4: MOPP 3 + دەستکێش — پاراستنا تەمام.","دەرزیا خوەکار یا Atropine (Auto-Injector): بۆ ژەهرا ماددەیێن دەماری، ل دویڤ ڕێنمایێن پزیشکی؛ و ڕاهێنانا بەردەوام ل سەر MOPP."]}],media:[{kind:"video",src:"media/videos/mil_cbrn.mp4",title:"CBRN",description:"ناسین و پاراستن"},{kind:"image",src:"media/images/mil_mopp.png",title:"ئاستێن MOPP",description:"٤ ئاست"}],quiz:[{question:"CBRN کورتکرنا چ یە؟",options:[{text:"فەرماندەیی، بنکە، ڕادیۆ، تۆڕ",correct:!1},{text:"کیمیایی، بایۆلۆژی، تیشکی، ئەتۆمی",correct:!0},{text:"کیمیایی، بۆمب، مووشەک، ماددەیێن دەماری",correct:!1},{text:"بەرگرییا شارستانی، سنوور، ڕزگارکرن، کارەساتێن سروشتی",correct:!1}],explanation:"کیمیایی (Chemical)، بایۆلۆژی (Biological)، تیشکی (Radiological)، ئەتۆمی (Nuclear)."},{question:"سێ فاکتەرێن پاراستنێ ژ تیشکان کیژن؟",options:[{text:"ئاڤ، خوارن، هەوا",correct:!1},{text:"دەم، دووراهی، ڕێگر",correct:!0},{text:"ڕاکرن، فشار، گەرمی",correct:!1},{text:"ڕادیۆ، مۆبایل، ساتەلایت",correct:!1}],explanation:"دەمێ کێم، دووراهیا زێدە و ڕێگرێ ستویر (Time, Distance, Shielding)."},{question:"Atropine بۆ چ یە؟",options:[{text:"سۆتن و برینێن پێستی",correct:!1},{text:"خوینبەربوون ژ برینێن مەزن",correct:!1},{text:"ژەهرا ماددەیێن دەماری",correct:!0},{text:"شکەستن",correct:!1}],explanation:"Atropine دەرمانەکە دژی ژەهرا ماددەیێن دەماری (Nerve Agents)."}]},{id:6,code:"MIL-106",icon:"Bomb",accent:"#ea580c",title:"مەترسیا مینان و IED",subtitle:"Mine Awareness & IED Safety",summary:"ناسینا مەترسیا مینان و بۆمبێن دەستکرد (IED) و خوەپاراستن",blocks:[{body:"مین و بۆمبێن دەستکرد مەترسیەکا ئاشکرانە ل هەرێما کوردستانێ. ئەڤ مەترسییە تەنێ یا سەربازان نینە — شارستانی ژی دبنە قوربانی."},{heading:"١. جۆرێن مینان",body:"مینێن سەرەکی:",points:["مینا دژی پیادەیان (AP): ب فشارا پێی دتەقیت.","مینا دژی ترمبێلان (AT): فشارەکا مەزنتر دڤێت.","مینا تەلێ (Tripwire): تەلەکا زراڤ کو ب زەحمەت دهێتە دیتن.","Claymore: ژ دوور ڤە دهێتە تەقاندن.","بۆمبێن هێشووی (Cluster): بچویک و ڕەنگینن — زارۆک وەک یاریێ دبینن!","نیشانێن ناڤچا مینان: تابلۆیێن سۆر (کەلەخ یان «مین»)، بەردێن ب ڕەنگێ سۆر، تەلێن دەوروبەر — هەرگز ژێ دەرباز نەبە."]},{heading:"٢. IED — بۆمبێن دەستکرد",body:"جۆر:",points:["RCIED: ب ڕێکا ڕیمۆت یان مۆبایلێ دهێتە تەقاندن.","VOIED: دەمێ قوربانی دەستێ خوە لێ ددەت یان پێ ل سەر ددانیت.","Timed IED: ب دەمژمێرێ (تایمەر).","VBIED: ترمبێلەکا بۆمبڕێژکری.","نیشانە: وایەرێن نەناس، ترمبێلا بەرزەکری، ئاخا نوو هاتیە کۆلان.","ئەگەر تە دیت: نێزیک نەبە! دوور بکەڤە و ئاگەهدار بکە."]},{heading:"٣. پێنج C یێن IED (5Cs)",body:"٥ هەنگاڤ:",points:["١. Confirm: ژ دووری ڤە پشتڕاست بە — نێزیک نەبە و دەست نەدێ.","٢. Clear: هەمی کەسان دوور بکە، لانیکێم ٣٠٠ مەتر.","٣. Call: ڕاپۆرتێ بدە فەرماندەیا خوە و تیمێ EOD، و گازی ١١٥ بکە.","٤. Cordon: ناڤچێ ببەستە و ژ بۆمبا دووێ (Secondary) هشیار بە.","٥. Control: کۆنترۆلا ناڤچێ بکە هەتا تیمێ EOD دگەهیت.","دووراهی: لانیکێم ٣٠٠ مەتر بۆ IED؛ بۆ VBIED پتر: نێزیکی ٦٠٠ مەتر بۆ ترمبێلەکا بچویک و هەتا ٢٨٠٠ مەتر بۆ بارهەلگرەکێ مەزن."]},{heading:"٤. هشیاریا شارستانی",body:"فێرکرنا خەلکی:",points:["زارۆک: دەست نەدەنە تشتێن نەناس!","جوتیار و ئاڤاکەر: بەری کۆلانا ئەردی، ژ لایەنێن پەیوەندیدار بپرسن؛ نەبوونا نیشانێن ئاگەهداریێ ب واتایا هندێ نینە کو ئەرد سەلامەتە، چونکی پترییا ناڤچێن مەترسیدار نیشانکری نینن.","شڤان: پەزی ل ناڤچێن مینان نەچەرینن.","نیشانێن ئاگەهداریا مینان بناسە، ڕێزێ ل وان بگرە و هەرگز وان ڕانەکە.","ئەگەر تە مینەک یان هەر تشتەکێ نەناس دیت: نێزیک نەبە، خەلکی ئاگەهدار بکە و ژێ دوور بێخە، جهێ وێ ژ بیر نەکە و بۆ لایەنێن پەیوەندیدار ڕاگەهینە؛ د تەنگاڤیێ دا گازی ١١٥ بکە.","هەرگز دەست نەدێ و هەلنەگرە — مرنە!","ئەگەر تە زانی کو بەلکی تو د ناڤچەکا مینان دا بی: ئێکسەر ڕاوەستە، بێ لڤین بمینە و پێیێن خوە نەلڤینە، گازی هاریکاریێ بکە و چاڤەڕێ بە هەتا تیمەکا ڕاهێنای دگەهیت."]}],media:[{kind:"video",src:"media/videos/mil_mine.mp4",title:"مین و IED",description:"ناسین و خوەپاراستن"},{kind:"image",src:"media/images/mil_mine_types.png",title:"جۆرێن مینان",description:"وێنە"}],quiz:[{question:"ئەگەر تە IED دیت، دێ چ کەی؟",options:[{text:"بچە نێزیکی",correct:!1},{text:"دەستێ خوە لێ بدە",correct:!1},{text:"دوور بکەڤە و ئاگەهدار بکە",correct:!0},{text:"نێزیک ببە و وێنێ بگرە",correct:!1}],explanation:"دوور بکەڤە، کەسان دوور بکە و ئاگەهداریا فەرماندەیا خوە و تیمێ EOD بکە."},{question:"دووراهیا سەلامەت ژ ترمبێلەکا بۆمبڕێژکری (VBIED) چەندە؟",options:[{text:"١٠٠ مەتر، بۆ هەمی جۆرێن ترمبێلان وەک ئێک",correct:!1},{text:"لانیکێم ٣٠٠ مەتر بۆ ترمبێلەکا بچویک، و ٦٠٠ مەتر بۆ ترمبێلێن مەزنتر",correct:!1},{text:"لانیکێم ٦٠٠ مەتر بۆ ترمبێلەکا بچویک، و پتر بۆ ترمبێلێن مەزنتر",correct:!0},{text:"٥٠ مەتر ئەگەر تو ل پشت دیوارەکی بی",correct:!1}],explanation:"ل دویڤ کارتا دووراهیێ یا CISA و FBI: ترمبێلەکا بچویک نێزیکی ٦٠٠ مەتر، ڤان یان SUV نێزیکی ٧٣٠ مەتر، و بارهەلگرێن مەزن ١٢٠٠-٢٨٠٠ مەتر."},{question:"بۆمبێن هێشووی (Cluster) بۆچی بۆ زارۆکان مەترسیدارن؟",options:[{text:"چونکی مەزن و گرانن",correct:!1},{text:"بچویک و ڕەنگینن — وەک یاریێ دیار دبن",correct:!0},{text:"چونکی ناتەقن",correct:!1},{text:"چونکی تەنێ بۆ کوشتنا سەربازان هاتینە چێکرن",correct:!1}],explanation:"بچویک و ڕەنگینن، زارۆک وان وەک یاری هەلدگرن."}]},{id:7,code:"MIL-107",icon:"Compass",accent:"#0d9488",title:"مانا ب ساخی و دیتنا ئاراستێ",subtitle:"Survival Skills & Navigation",summary:"هونەرێن مانا ب ساخی ل میدانێ، دیتنا ئاراستێ و ڕزگاربوون",blocks:[{body:"ل دۆخێن میدانی، دبیت پێشمەرگە ژ تیمێ خوە جودا ببیت. ئاڤ، ئاگر، پەناگەه و ئاراستە چار ستوینێن مانا ب ساخی نە."},{heading:"١. ئاڤ — گرنگیا ئێکێ",body:"ب گشتی مرۆڤ نێزیکی ٣ ڕۆژان بێ ئاڤ دژیت، و ل گەرمێ کێمتر:",points:["سەرچاڤە: ڕووبار، کانی، باران، خوناڤ.","کەلاندن: ١ خولەکێ ب کەلەکەل (ل بلندیا ژ ٢٠٠٠ مەتران پتر: ٣ خولەک).","حەبێن پاقژکرنێ: کلۆر یان یۆد (Chlorine/Iodine)، ل دویڤ ڕێنمایێن سەر پاکەتی.","فلتەرکرن: ب پەڕۆیەکێ پاقژ فلتەر بکە، پاشان بکەلینە.","ئاڤا ڕاوەستیای بێ پاقژکرن نەڤەخوە.","هەمیشە شووشەیەکا ئاڤێ دگەل خوە ببە."]},{heading:"٢. ئاگر",body:"ئاگر = گەرمی + ڕووناهی + ئاماژە:",points:["سێگۆشەیا ئاگری: سۆتەمەنی + ئۆکسجین + گەرمی.","دارێ هشک: ژ چقێن بچویک دەستپێ بکە.","هەلکرن: چەقماق، شقارتە، یان بەرد و ئاسن.","ماوە د ناڤبەرا داران دا بهێلە دا هەوا بگەهیتێ.","جهەکێ پاقژکری ژ گیایێ هشک هەلبژێرە و دەوروبەرێ ئاگری ب بەردان بگرە.","سێ ئاگر ب شێوێ سێگۆشەیێ = ئاماژەیا هەوارێ (SOS)."]},{heading:"٣. پەناگەه",body:"پاراستن ژ کەش و هەوایێ:",points:["شکەفت: باشترین پەناگەهن، بەلێ ژ هەرفتنێ و ئاژەلان هشیار بە.","چق و لقێن داران.","بەرد و ئاخ.","دەرگەهێ پەناگەهێ بەرەڤ بای نەبیت.","ئاگر نێزیکی پەناگەهێ، بەلێ ب دووراهیەکا سەلامەت.","خوە ژ ساریا ئەردی بپارێزە (چق، گیا یان کارتۆن ل بن خوە دانە)."]},{heading:"٤. دیتنا ئاراستێ",body:"بێ GPS:",points:["قیبلەنما (کۆمپاس): ئاراستە و سمت (Azimuth).","ڕۆژ: ژ ڕۆژهەلاتێ دەردکەڤیت و ل ڕۆژئاڤا ئاڤا دبیت.","ستێرا باکوور (Polaris): ئاراستا باکوور نیشان ددەت.","کەڤز ل سەر داران نیشانەکا باوەرپێکری نینە بۆ دیتنا باکووری.","ئاڤ بەرەڤ خوارێ دچیت؛ ل دویڤ ڕووباری بچە بەرەڤ گوند و ڕێکان.","سێ دەنگ، سێ ئاگر یان سێ ڕووناهی = ئاماژەیا هەوارێ (SOS)."]}],media:[{kind:"video",src:"media/videos/mil_survival.mp4",title:"مانا ب ساخی",description:"هونەرێن سەرەکی"}],quiz:[{question:"ب گشتی، مرۆڤ دشێت چەند ڕۆژان بێ ئاڤ بژیت؟",options:[{text:"١",correct:!1},{text:"٣",correct:!0},{text:"٧",correct:!1},{text:"١٤",correct:!1}],explanation:"نێزیکی ٣ ڕۆژان (یاسایا سێیان)؛ ل گەرمێ دەم گەلەک کێمترە."},{question:"سێ ئاگر ب شێوێ سێگۆشەیێ چ واتایێ ددەن؟",options:[{text:"هۆشداری بۆ دوورکەفتنێ",correct:!1},{text:"SOS — داخوازا هاریکاریێ",correct:!0},{text:"ئاگرێ دارستانێ بەلاڤ دبیت",correct:!1},{text:"چ واتا نینە",correct:!1}],explanation:"ئاماژەیەکا جیهانی یە بۆ داخوازا هاریکاریێ (SOS)."},{question:"ئاڤ دڤێت چەند بهێتە کەلاندن دا کو ڤەخوارنا وێ سەلامەت بیت؟",options:[{text:"تەنێ هەتا ئێکەم بلقێن بچویک ل بنێ مەنجەلێ دیار دبن",correct:!1},{text:"١٠ چرکە، پاشان دڤێت داپۆشی بهێتە هێلان هەتا سار ببیت",correct:!1},{text:"١ خولەکێ ب کەلەکەل؛ ل بلندیا ژ ٢٠٠٠ مەتران پتر، ٣ خولەک",correct:!0},{text:"لایێ کێم ٣٠ خولەک، ئەگەر نە میکرۆب دمینن",correct:!1}],explanation:"ئاڤێ ١ خولەکێ ب کەلەکەل بکەلینە (ل بلندیا ژ ٢٠٠٠ مەتران پتر: ٣ خولەک)؛ ئاڤا ڕاوەستیای بێ پاقژکرن نەڤەخوە."}]},{id:8,code:"MIL-108",icon:"Truck",accent:"#4b5563",title:"سەلامەتیا ترمبێل و کاروانان",subtitle:"Vehicle & Convoy Safety",summary:"سەلامەتیا ڤەگوهاستنا سەربازی و کاروانان",blocks:[{body:"ڕووداوێن هاتوچۆیێ، کەمین و بۆمبێن دەستکرد (IED) ل سەر ڕێکان مەترسیێن سەرەکینە."},{heading:"١. ڕێسایێن ئاژوتنا سەربازی",body:"بنەما:",points:["کلاوێ پاراستنێ هەمیشە.","ل ترمبێلا ڤەکری سواران زێدە نەکە.","قایشا سەلامەتیێ (کەمەربەند) بۆ هەمی سواران.","ڕادیۆ: پەیوەندیا بەردەوام.","ل ناڤچێن مەترسیدار تەنێ ل سەر ڕێکێن پاقژکری بچە و ژ ڕێکێ دەرنەکەڤە.","ل شەڤێ: ڕووناهیێن ترمبێلێ ل دویڤ ڕێنمایێن فەرماندەیێ."]},{heading:"٢. ڕێکخستنا کاروانی",body:"ڕێسا:",points:["ماوە د ناڤبەرا ترمبێلان دا: ٥٠-١٠٠ مەتر، ل دویڤ فەرمانا سەرۆکێ کاروانی.","هەر ترمبێلەک ڕادیۆیەک.","ترمبێلا هەوارهاتنێ: ل دویماهیێ.","ترمبێلا چاککرنێ: ل ناڤەڕاستێ.","ترمبێلا پێشڕەو: ٥٠٠ مەتر ل پێش.","ئاگەهداری (Briefing) بەری دەستپێکرنێ."]},{heading:"٣. کەمین",body:"ئەگەر کاروان کەفتە کەمینێ:",points:["ب لەز ژ ناڤچێ دەرباز ببە — ڕانەوەستە!","ڕاپۆرتا SALUTE ب لەز.","ئاراستا هێرشێ دیار بکە.","MARCH بۆ برینداران، دەمێ جه سەلامەت بوو.","داخوازا پشتەڤانیێ (Backup) بکە.","ژ IED یا دووێ ل سەر ڕێکێ هشیار بە."]},{heading:"٤. ڕووداوێن هاتوچۆیێ",body:"چ بکەین:",points:["ل جهەکێ سەلامەت ڕاوەستە.","سێگۆشەیا ئاگەهداریێ دانە.","MARCH بۆ برینداران.","گازی ١١٥ و ١٢٢ بکە.","ئاگر: هەمی کەسان دوور بکە و ل سەرێ بای بمینە؛ ئەگەر ترمبێلەکا کو تەقەمەنی تێدا هەبن کەفتە د ئاگری دا (ERG Guide 112، Division 1.1، 1.2، 1.3، 1.5): ١٦٠٠ مەتر (١ میل) ل هەمی ئالیان ناڤچێ ببەستە و ڤالا بکە، هەتا تیمێن تەنگاڤیێ ژی؛ ئەگەر ئاگر گەهشتە بارێ تەقەمەنیێ، ئاگری ڤەنەمرینە.","وێنە بگرە و ڕاپۆرتێ بنڤیسە."]}],media:[{kind:"video",src:"media/videos/mil_convoy.mp4",title:"کاروان",description:"ڕێکخستن"}],quiz:[{question:"ل دویڤ ڤێ وانێ، ماوەیێ ئاسایی د ناڤبەرا ترمبێلێن کاروانی دا چەندە؟",options:[{text:"١٠-٢٠ مەتر",correct:!1},{text:"٥٠-١٠٠ مەتر",correct:!0},{text:"٢ مەتر",correct:!1},{text:"٣٠٠-٥٠٠ مەتر",correct:!1}],explanation:"٥٠-١٠٠ مەتر، ل دویڤ دۆخی و فەرمانا سەرۆکێ کاروانی."},{question:"ل دەمێ کەمینێ، شۆفێر دێ چ کەت؟",options:[{text:"ڕادوەستیت و چاڤەڕێی هاریکاریێ دکەت",correct:!1},{text:"ب لەز ژ ناڤچێ دەرباز دبیت",correct:!0},{text:"ژ ترمبێلێ دادبەزیت",correct:!1},{text:"ڕادوەستیت دا وێنە بگریت",correct:!1}],explanation:"ب لەز ژ ناڤچا کەمینێ دەرباز ببە، ئەگەر ڕێک ڤەکری بیت."},{question:"ل ناڤچێن مەترسیدار، ترمبێلێن سەربازی دڤێت ل کیرێ بچن؟",options:[{text:"ل دەرڤەی ڕێکێ، دا کو ژ IED یێن د ناڤ قیرێ دا ڤەشارتی دوور بن",correct:!1},{text:"ل سەر کورتترین ڕێک، دا کو دەمەکێ کێمتر د مەترسیێ دا بمینن",correct:!1},{text:"ل سەر کەنارێ ڕێکێ، دا کو ترمبێلێن دی دەرباز ببن",correct:!1},{text:"تەنێ ل سەر ڕێکێن پاقژکری، بێ دەرکەفتن ژ ڕێکێ",correct:!0}],explanation:"ل ناڤچێن مەترسیدار تەنێ ل سەر ڕێکێن پاقژکری بچە و ژ ڕێکێ دەرنەکەڤە؛ بۆمبێن دەستکرد (IED) ل سەر ڕێکان ئێکن ژ مەترسیێن سەرەکی."}]},{id:9,code:"MIL-109",icon:"Droplets",accent:"#0284c7",title:"پاقژکرنا ئاڤێ و پاقژیا کەسی",subtitle:"Water Purification & Hygiene",summary:"پاقژکرنا ئاڤێ و پاقژیا کەسی ل میدانێ",blocks:[{body:"نەخۆشیێن ئاڤا پیس دشێن ژ دوژمنی مەترسیدارتر بن! ئاڤا پیس هێزان لاواز دکەت."},{heading:"١. پاقژکرنا ئاڤێ",body:"٤ ڕێک:",points:["کەلاندن: ١ خولەکێ ب کەلەکەل — باوەرپێکریترین ڕێکە بۆ کوشتنا میکرۆبان.","حەبێن کلۆر/یۆد: ل دویڤ ڕێنمایێن سەر پاکەتی، و ٣٠ خولەکان چاڤەڕێ بە.","فلتەرێن تایبەت (وەک LifeStraw).","SODIS: شووشێن پلاستیکی یێن ڕۆهن، ٦ دەمژمێران ل بەر تاڤا ڕۆژێ (ئەگەر ئەور هەبیت: ٢ ڕۆژ).","ئاڤا ڕاوەستیای بێ پاقژکرن نەڤەخوە.","ڕێزبەندی: ئێکەم بهێلە تەقن بنیشیت، پاشان فلتەر بکە، پاشان پاقژ بکە."]},{heading:"٢. پاقژیا کەسی",body:"ل میدانێ:",points:["دەست شویشتن: بەری خوارنێ و پشتی دەستاڤێ.","لەشی ب بەردەوامی پاقژ بکە؛ ئەگەر ئاڤ کێم بیت، ب پەڕۆیەکێ تەڕ.","گۆرەویان ڕۆژانە بگوهۆڕە و جلکان پاقژ بهێلە.","پێیان پاقژ و هشک بهێلە.","برینێن بچویک: بشۆ و ب پێچانەکا پاقژ دابپۆشە.","ددانان ڕۆژێ ٢ جاران بشۆ."]},{heading:"٣. خوارن",body:"سەلامەتیا خوارنێ:",points:["دیرۆکا ب دویماهی هاتنێ بپشکنە.","خوارنێ ب تەمامی بپێژە (ناڤەڕاستا وێ ٧٥°C).","خوارنا پێژای پتر ژ ٢ دەمژمێران ل گەرمیا ژوورێ نەهێلە (ل گەرمیا ژ ٣٢°C پتر: ١ دەمژمێر).","خوارنێ ژ مێش و تۆزێ دابپۆشە.","پاشماوێن خوارنێ دوور ژ کامپی بسۆژە یان ڤەشێرە.","ئاڤا پاقژ گەلەک ڤەخوە."]},{heading:"٤. نەخۆشیێن میدانی",body:"یێن بەربەلاڤ:",points:["زکچوون: شلەیا ئاڤ، خوێ و شەکرێ (ORS) ڤەخوە.","مالاریا: تۆڕا پێشییان و سپرایا دژی مێشان.","گەرمالێدان (Heat Stroke): سێبەر، ساردکرنا ب لەز و گازی ١٢٢ بکە.","سەرمابوون (Hypothermia): ب هێدی گەرم بکە و جلکێن تەڕ بکە دەر.","ئینفێکشن: پێچانێ ڕۆژانە بگوهۆڕە، یان دەمێ تەڕ یان پیس بوو.","هەر نەخۆشیەکێ ڕاپۆرت بکە بۆ پزیشکی."]}],media:[{kind:"video",src:"media/videos/mil_water.mp4",title:"ئاڤ",description:"پاقژکرن"}],quiz:[{question:"باوەرپێکریترین ڕێکا پاقژکرنا ئاڤێ کیژە؟",options:[{text:"حەب",correct:!1},{text:"کەلاندن",correct:!0},{text:"فلتەر",correct:!1},{text:"تاڤا ڕۆژێ",correct:!1}],explanation:"کەلاندنا ١ خولەکێ ب کەلەکەل، باوەرپێکریترین ڕێکە بۆ کوشتنا میکرۆبێن نەخۆشیێ."},{question:"خوارنا پێژای هەتا چەند دەمژمێران دشێت ل گەرمیا ژوورێ بمینیت؟",options:[{text:"نە پتر ژ ١٢ دەمژمێران (ل هەوایێ گەرم: ٦ دەمژمێر)",correct:!1},{text:"نە پتر ژ ٢ دەمژمێران (ل گەرمیا ژ ٣٢°C پتر: ١ دەمژمێر)",correct:!0},{text:"هەتا ٢٤ دەمژمێران ئەگەر سەرگرتی بیت",correct:!1},{text:"فەرق ناکەت",correct:!1}],explanation:"ل دویڤ ڕێنمایێن WHO، خوارنا پێژای پتر ژ ٢ دەمژمێران ل گەرمیا ژوورێ نەهێلە؛ ل گەرمیا ژ ٣٢°C پتر، ١ دەمژمێر (USDA)."},{question:"ئاڤا میدانێ ب کیش ڕێزبەندی دهێتە پاقژکرن؟",options:[{text:"ئێکەم بهێلە تەقن بنیشیت، پاشان فلتەر بکە، پاشان پاقژ بکە",correct:!0},{text:"ئێکەم پاقژ بکە، پاشان فلتەر بکە، پاشان بهێلە تەقن بنیشیت",correct:!1},{text:"ئێکەم فلتەر بکە، پاشان پاقژ بکە، پاشان بهێلە تەقن بنیشیت",correct:!1},{text:"ئێکەم پاقژ بکە، پاشان بهێلە تەقن بنیشیت، پاشان فلتەر بکە",correct:!1}],explanation:"ڕێزبەندییا وانێ ئەڤەیە: ئێکەم بهێلە تەقن بنیشیت، پاشان فلتەر بکە، پاشان پاقژ بکە."}]},{id:10,code:"MIL-110",icon:"Thermometer",accent:"#ea580c",title:"گەرما و سەرما — مەترسیێن کەش و هەوایێ",subtitle:"Heat & Cold Weather Operations",summary:"مەترسیێن گەرمێ و سەرمایێ و خوەپاراستن",blocks:[{body:"ل هەرێما کوردستانێ، گەرما ل هاڤینێ دگەهیتە نێزیکی ٥٠°C، و ل زڤستانێ ل چیایان دبیت ژ -١٥°C نزمتر ببیت."},{heading:"١. مەترسیێن گەرمێ",body:"گەرمالێدان (Heat Stroke) دکوژیت:",points:["وەستیانا ژ گەرمێ (Heat Exhaustion): سەرئێشان، دلتێکهەلاتن، ڤەڕەشیان، خوهدانا زێدە.","گەرمالێدان: پلەیا لەشی ٤٠°C یان پتر و تێکچوونا هشی — تەنگاڤی! ئێکسەر سار بکە و گازی ١٢٢ بکە.","ئاڤ: نێزیکی ١ لیتر ل دەمژمێرێ ل کارێ گران؛ نە پتر ژ ١٫٤ لیتران ل دەمژمێرێ.","دەمێن کار و بێهنڤەدانێ ل دویڤ پلەیا گەرمیێ (WBGT)؛ بێهنڤەدان ل سێبەرێ.","ساردکرنا گەرمالێدانێ: ئێکسەر و بەری ڤەگوهاستنێ؛ باشترین ڕێک: هەمی لەش هەتا ستوی د ناڤ ئاڤا سار دا بۆ ١٥ خولەکان یان هەتا هشێ وی دووبارە ڕوون دبیت، کیژ ژ وان زووتر بیت؛ ئەگەر نەشیای: دووشا سار، خاولی یان چەرچەفێن تەڕ و سار، کیسێن قەشایێ و باوەشێنکرن؛ هەتا هشێ وی تێکچووی بیت چ ڤەخوارنێ نەدەیێ.","جلکێن ڕەنگ ڤەکری و سڤک."]},{heading:"٢. مەترسیێن سەرمایێ",body:"سەرمابوونا لەشی (Hypothermia) و قەرسین (Frostbite):",points:["سەرمابوون: پلەیا لەشی ژ ٣٥°C نزمتر.","قەرسین: قەرسینا تبلان، گوهان و دفنێ.","جلکێن قات ب قات.","ب هێدی گەرم بکە — نە ب ئاگرێ ڕاستەوخۆ.","قەرسین: نەمالێنە! ل ئاڤا گەرم (٣٧-٣٩°C) دانە، تەنێ ئەگەر جارەکا دی نەقەرسیت.","ئەگەر لەرزین ڕاوەستیا و هشێ کەسی تێکچوو — تەنگاڤییە! گازی ١٢٢ بکە."]},{heading:"٣. جلکێن قات ب قات",body:"سیستەمێ سێ قاتان:",points:["١. قاتا نێزیکی پێستی (Base Layer): خوهێ ژ لەشی دوور دکەت.","٢. قاتا گەرمکەر (Insulation): وەک فلیس.","٣. قاتا دەرڤە (Shell): دژی با و بارانێ.","دەستکێشێن ستویر.","کلاو و شال: گەرمی ژ هەر جهەکێ لەشی یێ نەپۆشای دچیت، نەک تەنێ ژ سەری — هەمی لەشی داپۆشە.","پوتینێن دژی ئاڤێ."]}],media:[{kind:"video",src:"media/videos/mil_weather.mp4",title:"کەش و هەوا",description:"گەرما و سەرما"}],quiz:[{question:"ل کارێ گران د گەرمێ دا، نێزیکی چەند ئاڤ ل دەمژمێرێ ڤەدخوین؟",options:[{text:"تەنێ دەمێ تێهنی ببی",correct:!1},{text:"نێزیکی ١ لیتر (نە پتر ژ ١٫٤ لیتران)",correct:!0},{text:"نێزیکی ٢ لیتر (نە کێمتر ژ ١٫٥ لیتران)",correct:!1},{text:"٣ لیتر",correct:!1}],explanation:"ل دویڤ ڕێنمایێن سوپایێ ئەمریکی (TB MED 507): ل کارێ گران نێزیکی ١ لیتر ل دەمژمێرێ؛ پتر ژ ١٫٤ لیتران ل دەمژمێرێ دبیتە ئەگەرێ کێمبوونا خوێیا لەشی."},{question:"ل قەرسینێ (Frostbite)، کیژ کار خەلەتە؟",options:[{text:"جهێ قەرسی بمالێنە یان بەفرێ لێ بدە",correct:!0},{text:"جهێ قەرسی ل ئاڤا گەرم (٣٧-٣٩°C) دانە",correct:!1},{text:"جلکێن تەڕ و توند بکە دەر",correct:!1},{text:"بریندارێ ببە جهەکێ گەرم و پاراستی",correct:!1}],explanation:"مالاندن، بەفر و ئاگرێ ڕاستەوخۆ زیانێ ددەنە پێستی؛ ب ئاڤا گەرم (٣٧-٣٩°C) گەرم بکە."},{question:"ل دویڤ ڤێ وانێ، بریندارێ گەرمالێدانێ چەوا دهێتە ساردکرن؟",options:[{text:"تەنێ پشتی ڤەگوهاستنێ بۆ نەخۆشخانێ، دا کو ساردکرن ڕێکێ دەرەنگ نەکەت",correct:!1},{text:"ئێکسەر و بەری ڤەگوهاستنێ؛ باشترین ڕێک: لەش هەتا ستوی د ناڤ ئاڤا سار دا",correct:!0},{text:"ب دانا گەلەک ئاڤا سار بۆ ڤەخوارنێ دەمێ هشێ وی هێشتا تێکچوویە",correct:!1},{text:"ب هێدی، ب پەڕۆیەکێ تەڕ ل سەر ئەنیێ، دا کو لەش تووشی شۆکێ نەبیت",correct:!1}],explanation:"گەرمالێدانێ ئێکسەر و بەری ڤەگوهاستنێ سار بکە: باشترین ڕێک هەمی لەش هەتا ستوی د ناڤ ئاڤا سار دا بۆ ١٥ خولەکان یان هەتا هشێ وی دووبارە ڕوون دبیت، کیژ ژ وان زووتر بیت؛ هەتا هشێ وی تێکچووی بیت چ ڤەخوارنێ نەدەیێ، و گازی ١٢٢ بکە."}]},{id:11,code:"MIL-111",icon:"Ambulance",accent:"#dc2626",title:"ڤەگوهاستنا برینداران (MEDEVAC)",subtitle:"Casualty Evacuation & 9-Line",summary:"ڤەگوهاستنا سەلامەت و داخوازا 9-Line MEDEVAC",blocks:[{body:"هەوارهاتنا ئێکێ ئێکەم هەنگاڤە، بەلێ ڤەگوهاستنا ب لەز بۆ نەخۆشخانێ ژیانێ ڕزگار دکەت."},{heading:"١. هەلگرتنا برینداران",body:"تەکنیک:",points:["ب ٢ کەسان: ئێک ل لایێ سەری و ئێک ل لایێ لنگان.","هەلگرتن ل سەر ملی (Fireman Carry): ب ئێک کەسی — ب لەز.","برانکارد: ب ٤ کەسان — باشترین.","برانکاردا دەستکرد: ٢ دار و چاکێتەک یان بەتانیەک.","گۆمانا برینا ستوی یان پشتێ: نەلڤینە، ئەگەر مەترسیا ئاگری یان تەقینێ نەبیت.","سەر، ستوی و پشت پێکڤە و ل سەر ئێک هێلێ بلڤینە."]},{heading:"٢. 9-Line MEDEVAC",body:"٩ خال:",points:["Line 1: جهێ هەلگرتنێ (کۆئۆردینات / GPS).","Line 2: فریکوێنسیا ڕادیۆیێ و ناڤێ بانگکرنێ (Call Sign).","Line 3: ژمارا برینداران ل دویڤ پێشینیێ (Urgent، Priority، Routine).","Line 4: کەرەستێن تایبەت (وەک Hoist).","Line 5: ژمارا برینداران ل دویڤ جۆری: L ل سەر برانکاردێ، A دشێن بڕێڤە بچن.","Line 6: ئاسایشا جهی: N دوژمن نینە، P دبیت دوژمن هەبیت، E دوژمن یێ هەی، X پاراستنا چەکداری پێدڤییە.","Line 7: ڕێکا نیشانکرنا جهی (پانێل، دوکێلا ڕەنگین، ڕووناهی).","Line 8: نەتەوە و ڕەوشا برینداران (سەرباز، شارستانی، دیل).","Line 9: پیسبوونا CBRN ل دەمێ شەڕی؛ یان وەسفا ئەردێ جهی ل دەمێ ئاشتیێ."]},{heading:"٣. جهێ دابەزینا هەلیکۆپتەرێ (LZ)",body:"بۆ هەلیکۆپتەرێ:",points:["مەزناهی: بازنەیەک ب تیرەیا لانیکێم ٣٥ مەتر بۆ هەلیکۆپتەرا سڤک (وەک UH-1)، ٥٠ مەتر بۆ UH-60، و ٨٠ مەتر بۆ هەلیکۆپتەرێن بارهەلگر.","بێ تەل، دار و ئاستەنگێن بلند؛ ئەرد ڕاست و پاقژ.","ئاراستا بای دیار بکە (هەلیکۆپتەر بەرەڤ بای دنیشیت).","ل شەڤێ: ٤ ڕووناهی ب شێوێ Y یێ سەرەوژێر.","تۆز و تشتێن سڤک ژ جهی لابە، چونکی بایێ پەروانێ وان دفڕینیت.","٣٠ مەتر دوور بمینە هەتا ئاماژە بۆ تە دهێتە دان."]}],media:[{kind:"video",src:"media/videos/mil_medevac.mp4",title:"MEDEVAC",description:"ڤەگوهاستن"},{kind:"image",src:"media/images/mil_9line.png",title:"9-Line",description:"فۆرم"}],quiz:[{question:"کێمترین مەزناهیا جهێ دابەزینێ (LZ) بۆ هەلیکۆپتەرەکا سڤک (وەک UH-1) چەندە؟",options:[{text:"١٠ مەتر",correct:!1},{text:"٢٠ مەتر",correct:!1},{text:"٣٥ مەتر",correct:!0},{text:"٥ مەتر",correct:!1}],explanation:"بازنەیەک ب تیرەیا ٣٥ مەتر بۆ هەلیکۆپتەرا سڤک؛ هەلیکۆپتەرێن مەزنتر جهەکێ مەزنتر دڤێن (٥٠ مەتر بۆ UH-60)."},{question:"د 9-Line دا، Line 1 چ یە؟",options:[{text:"ژمارا برینداران ل دویڤ پێشینیێ",correct:!1},{text:"جهێ هەلگرتنێ (کۆئۆردینات)",correct:!0},{text:"ئاسایشا جهی",correct:!1},{text:"فریکوێنسیا ڕادیۆیێ و ناڤێ بانگکرنێ",correct:!1}],explanation:"Line 1 جهێ هەلگرتنێ یە ب کۆئۆردیناتان."},{question:"گۆمانا برینا ستوی یان پشتێ ل برینداری هەیە. کەنگی دشێی وی بلڤینی؟",options:[{text:"هەر دەمێ دوو کەس هەبن کو وی هەلگرن",correct:!1},{text:"دەمێ ئەو دبێژیت هەست ب دەست و لنگێن خوە دکەت",correct:!1},{text:"تەنێ ئەگەر مەترسیا ئاگری یان تەقینێ هەبیت",correct:!0},{text:"هەر دەمێ جهێ دابەزینا هەلیکۆپتەرێ ئامادە بیت",correct:!1}],explanation:"ل گۆمانا برینا ستوی یان پشتێ، بریندارێ نەلڤینە ئەگەر مەترسیا ئاگری یان تەقینێ نەبیت؛ ئەگەر پێدڤی بوو، سەر، ستوی و پشت پێکڤە و ل سەر ئێک هێلێ بلڤینە."}]},{id:12,code:"MIL-112",icon:"Search",accent:"#d97706",title:"لێگەڕیان و ڕزگارکرن (SAR)",subtitle:"Search & Rescue Operations",summary:"ئۆپەراسیۆنێن لێگەڕیان و ڕزگارکرنا کەسان",blocks:[{body:"ل دەمێ عەردەهەژین، لەهی و تەقینان، خەلک ل بن کەلاوەیان دمینن. پێشمەرگە گەلەک جاران ئێکەم کەسن کو دگەهنە جهی."},{heading:"١. ڕێکێن لێگەڕیانێ",body:"شێوە:",points:["هێلی: ڕیز ب ڕیز، ب ماوەیەکێ ڕێک.","پێچپێچی (Spiral): ژ ناڤەڕاستێ بەرەڤ دەرڤە.","پارچەیی (Sector): ناڤچە بۆ پارچان دهێتە دابەشکرن.","سەیێن لێگەڕیانێ (K9).","ب دەمێن ڕێکخستی (بۆ نموونە هەر ١٠ خولەکان) بێدەنگیێ ڕاگەهینە و گوهداریێ بکە.","ب دەنگێ بلند گازی کەسان بکە و گوه بدە بەرسڤێ."]},{heading:"٢. ل بن کەلاوەیان",body:"ڕزگارکرن:",points:["جهێ کەسی بدۆزە: ب گوهداریێ و سەیێن لێگەڕیانێ.","دگەل قوربانیی باخڤە و ئارامیێ بدەیێ.","ب هێدی و هشیاری دەربێخە.","ژ مەترسیا هەرفتنا دووێ هشیار بە.","MARCH ئێکسەر بۆ برینداران.","گازی ١١٥ و ١٢٢ بکە."]},{heading:"٣. ڕزگارکرن ژ ئاڤێ",body:"لەهی و خەندقین:",points:["نەچە ناڤ ئاڤێ ئەگەر تە ڕاهێنانا ڕزگارکرنێ نەدیتی بیت.","ژ کەناری تشتەکێ درێژ بگەهینێ یان بهاڤێژێ: بەن، چق، جلکێ درێژ.","جەلەکا ڕزگاربوونێ (Life Jacket) بکە بەر خوە.","زنجیرا مرۆڤان تەنێ ل ئاڤا تەنک و هێدی.","پشتی کەس ژ ئاڤێ دەرکەفت، هەناسێ وی بپشکنە. ئەگەر ب دروستی هەناسە نەدا: گازی ١٢٢ بکە و ئەگەر تە ڕاهێنان دیتبیت، CPR دگەل هەناسان دەستپێ بکە (د خەندقینێ دا ئێکەم جار هەناسە ڕادوەستیت، ژبەر هندێ هەناسە ژ هەمی تشتان گرنگترن)؛ ئەگەر ڕاهێنان نەدیتبی یان نەشێی هەناسان بدەی، تەنێ فشارێن سنگی بدە. هەر کەسەکێ ژ ئاڤێ هاتبیتە دەرئێخستن دڤێت ب پزیشکی بهێتە پشکنین، هەتا ئەگەر باش ژی دیار بیت.","١٥ سم ئاڤا ڕەوان دشێت مرۆڤی بێخیت؛ ٣٠ سم دشێت ترمبێلێ ببەت."]}],media:[{kind:"video",src:"media/videos/mil_sar.mp4",title:"SAR",description:"لێگەڕیان و ڕزگارکرن"}],quiz:[{question:"ل دەمێ لێگەڕیانێ ل بن کەلاوەیان، ب دەمێن ڕێکخستی (بۆ نموونە هەر ١٠ خولەکان) چ دهێتە کرن؟",options:[{text:"هەمی دڕەڤن",correct:!1},{text:"بێدەنگی و گوهداریکرن",correct:!0},{text:"جلکان دگوهۆڕن",correct:!1},{text:"ئاڤێ ڤەدخۆن",correct:!1}],explanation:"هەمی کار ڕادوەستن و هەمی بێدەنگ دبن، دا کو دەنگێ قوربانیان بهێتە بهیستن."},{question:"ئەگەر کەسەک ل ئاڤێ دخەندقیت و تە ڕاهێنانا ڕزگارکرنێ نەدیتی بیت، دێ چ کەی؟",options:[{text:"ئێکسەر خوە دهاڤێمە ناڤ ئاڤێ و ب خوە دەردئێخم",correct:!1},{text:"ژ کەناری تشتەکێ درێژ دگەهینمێ یان دهاڤێژمێ",correct:!0},{text:"تەنێ ژ کەناری تەماشە دکەم هەتا کەسەکێ دی دهێت",correct:!1},{text:"دڕەڤم و جهی دهێلم",correct:!1}],explanation:"ژ کەناری تشتەکێ درێژ بگەهینێ یان بهاڤێژێ و گازی ١١٥ بکە؛ نەچە ناڤ ئاڤێ."},{question:"کەسەکێ ژ ئاڤێ هاتییە دەرئێخستن ب دروستی هەناسێ نادەت، و تە ڕاهێنان دیتییە. دێ چ کەی؟",options:[{text:"تەنێ فشارێن سنگی بدە، چونکی پشتی خەندقینێ هەناسە نە گرنگن",correct:!1},{text:"کەسی سەرەوژێر بکە دا کو ئاڤ ژ سییێن وی دەرکەڤیت",correct:!1},{text:"چاڤەڕێ بە هەتا کەس ئاڤێ ب کۆخکێ دەردئێخیت، پاشان کاری بکە",correct:!1},{text:"گازی ١٢٢ بکە و CPR دگەل هەناسان دەستپێ بکە",correct:!0}],explanation:"ئەگەر ب دروستی هەناسە نەدا، گازی ١٢٢ بکە و ئەگەر تە ڕاهێنان دیتبیت CPR دگەل هەناسان دەستپێ بکە: د خەندقینێ دا ئێکەم جار هەناسە ڕادوەستیت، ژبەر هندێ هەناسە ژ هەمی تشتان گرنگترن. هەر کەسەکێ ژ ئاڤێ هاتبیتە دەرئێخستن دڤێت ب پزیشکی بهێتە پشکنین."}]},{id:13,code:"MIL-113",icon:"Flame",accent:"#dc2626",title:"ئاگر ل بنکەیێن سەربازی و جەبەخانەیان",subtitle:"Fire Safety in Military Bases",summary:"ڕێگرتن ل ئاگری و دەرکەفتنا سەلامەت ل بنکەیێن سەربازی و جەبەخانەیان",blocks:[{body:"ئاگر ل بنکەیێن سەربازی مەترسیدارترە، چونکی چەک، تەقەمەنی و سۆتەمەنی لێ هەنە. ئەگەر ئاگر گەهشتە تەقەمەنیێ یان نێزیکی وێ بوو، ڤەمراندن نینە: دەرکەڤە، ناڤچێ ببەستە و گازی ١١٥ بکە."},{heading:"١. سەرچاڤێن ئاگری",body:"ل بنکەیان:",points:["تەقەمەنی.","بەنزین و مازووت.","سۆبێن چادران.","جەنەراتۆر.","جگارەکێشان.","تەلێن کارەبێ یێن خراب یان زێدەبارکری."]},{heading:"٢. تەمرینکێن ئاگری",body:"جۆر (پۆل ل دویڤ NFPA):",points:["تۆزا ABC: بۆ پۆلێن A، B و C — نە بۆ D (کانزا) و نە بۆ K (ڕۆنێ مەتبەخێ).","CO₂: بۆ ئاگرێ کارەبێ و ئامێران (C) و شلەمەنیان (B).","ئاگرێ تەقەمەنیێ ب تەمرینکێ ناهێتە ڤەمراندن: دەرکەڤە، ببەستە، گازی ١١٥ بکە.","P.A.S.S، تەنێ دەمێ هەمی بەرسڤێن پشکنینا بەری بکارئینانێ «بەلێ» بن (ئاگرەکێ بچووک و تازە؛ تەمرینکا گونجای؛ ڕێکا دەرکەفتنێ ل پشت تە؛ ئاگەهداری هاتییە دان و گازی ١١٥ هاتییە کرن؛ تو ڕاهێنان دیتی یی؛ چو دوکێل یان گەرمی ڕێکا تە ناگریت): بکێشە (Pull)، ئاراستێ بنێ ئاگری بکە (Aim)، فشار بدە (Squeeze)، بلڤینە (Sweep)؛ ئەگەر ئاگر ئێکسەر ڤەنەمری، دەرکەڤە.","تەمرینکان نێزیکی دەرگەهێن دەرکەفتنێ دانە.","پشکنینا هەیڤانە ب چاڤان و چاککرنا سالانە."]},{heading:"٣. جەبەخانە (کۆگەها تەقەمەنیێ)",body:"ڕێسایێن تایبەت:",points:["قەدەغە: جگارە، ئاگر، شقارتە، چەقماق و مۆبایل.","ژ گەرمیێ و تاڤا ڕۆژێ بپارێزە، ل دویڤ ڕێسایێن هەلگرتنا تەقەمەنیێ.","جلک و دەستکێشێن دژی کارەبا ستاتیک (Anti-static).","ئامێرێن دیتنا ئاگری و سپرینکلەرێن خوەکار.","تەنێ کەسێن ڕێپێدای دچنە ژوور.","تۆمارا تەمام: چ، چەند و ل کیڤەیە (بۆ ئاگەهداریا ١١٥)."]},{heading:"٤. پلانا دەرکەفتنێ",body:"ئەگەر ئاگر ل جەبەخانێ یان نێزیکی تەقەمەنیێ کەفت: ئاگری ڤەنەمرینە. دەرکەڤە، ناڤچێ ببەستە و گازی ١١٥ بکە.",points:["سیرێنێ لێ بدە و هەمیان ئاگەهدار بکە.","ب لەز دەرکەڤە ب ڕێکەکا دوور ژ جەبەخانێ (لانیکێم ٢ ڕێکێن دەرکەفتنێ).","ناڤچا ڤالاکرن و بەستنێ بۆ ئاگرێ جەبەخانێ: ئەو دووراهیا کو ڕێسایێن سەلامەتیا تەقەمەنیێ یێن فەرماندەیا تە بۆ وی جهی دیار دکەن. دووراهیا ERG Guide 112، ١٦٠٠ مەتر (١ میل) ل هەمی ئالیان، بۆ تەقەمەنیێن د ڤەگوهاستنێ دا یە (بارهەلگر یان ڤاگۆنا شەمەندەفەرێ د ئاگری دا، یان گەهشتنا ئاگری بۆ بارێ تەقەمەنیێ)؛ وێ وەک یاسا بۆ هەمی ئاگرێن جەبەخانان بکار نەئینە.","خالا کۆمبوونێ: دەرڤەی ناڤچا ڤالاکرنێ، ل سەرێ بای (ئالیێ بای ژێ دهێت)، ل پشت ڕێگرەکێ و دوور ژ هێلا دیتنێ و پەنجەرەیان.","سەرژمێری: هەمی کەس بهێنە هژمارتن؛ ناڤێن کەسێن بەرزە بدە ١١٥.","گازی ١١٥ بکە (جه، جۆر و بڕێ تەقەمەنیێ)."]}],media:[{kind:"video",src:"media/videos/mil_fire_base.mp4",title:"ئاگر",description:"بنکەیا سەربازی"}],quiz:[{question:"ل جەبەخانێ، چ قەدەغەیە؟",options:[{text:"تۆمارکرنا تەقەمەنیێ",correct:!1},{text:"جگارە، ئاگر و مۆبایل",correct:!0},{text:"ئاخفتن دگەل هەڤالان د دەمێ کاری دا",correct:!1},{text:"کرنا جلکێن دژی کارەبا ستاتیک",correct:!1}],explanation:"جگارە، ئاگر و مۆبایل قەدەغەنە، چونکی دشێن ئاگری یان تەقینێ چێکەن."},{question:"ل دویڤ ERG Guide 112، ئەگەر بارهەلگرەکێ کو تەقەمەنی تێدا هەبن کەفتە د ئاگری دا، دڤێت ناڤچا بەستن و ڤالاکرنێ چەند بیت؟",options:[{text:"٥٠ مەتر ل دۆر بارهەلگری، هەتا ئاگر دهێتە ڤەمراندن",correct:!1},{text:"١٠٠ مەتر ل هەمی ئالیان، ژبلی تیمێ ڤەمراندنا ئاگری",correct:!1},{text:"١٦٠٠ مەتر (١ میل) ل هەمی ئالیان، هەتا تیمێن تەنگاڤیێ ژی",correct:!0},{text:"٨٠٠ مەتر (نیڤ میل) ل هەمی ئالیان، و تیمێن تەنگاڤیێ ئاگری ڤەدمرینن",correct:!1}],explanation:"ERG Guide 112 (تەقەمەنیێن د ڤەگوهاستنێ دا، Division 1.1، 1.2، 1.3، 1.5): ئەگەر بارهەلگر یان ڤاگۆنا شەمەندەفەرێ کەفتە د ئاگری دا، ١٦٠٠ مەتر (١ میل) ل هەمی ئالیان ناڤچێ ببەستە و ڤالا بکە، هەتا تیمێن تەنگاڤیێ ژی؛ ئەگەر ئاگر گەهشتە بارێ تەقەمەنیێ، ئاگری ڤەنەمرینە و بهێلە بسوژیت. بۆ ئاگرێ جەبەخانێ، دووراهیا د ڕێسایێن سەلامەتیا تەقەمەنیێ یێن فەرماندەیا تە دا بکار بینە. خالا کۆمبوونێ دەرڤەی ناڤچا ڤالاکرنێ و ل سەرێ بای بیت."},{question:"ئاگر ل جەبەخانێ دکەڤیت. دێ چ کەی؟",options:[{text:"ئاگری ڤەنەمرینە: دەرکەڤە، ناڤچێ ببەستە و گازی ١١٥ بکە",correct:!0},{text:"تەمرینکا CO₂ ل سەر سندۆقێن تەقەمەنیێ یێن دسۆژن بکار بینە",correct:!1},{text:"سندۆقان ب ئاڤێ سار بکە هەتا یێن دی ژ بنکەیێ دەردکەڤن",correct:!1},{text:"تۆزا ABC بکار بینە، چونکی بۆ پۆلێن A، B و C یە",correct:!1}],explanation:"ئەگەر ئاگر ل جەبەخانێ یان نێزیکی تەقەمەنیێ کەفت، ئاگری ڤەنەمرینە: دەرکەڤە، ناڤچێ ببەستە و گازی ١١٥ بکە. ئاگرێ تەقەمەنیێ ب تەمرینکێ ناهێتە ڤەمراندن."}]},{id:14,code:"MIL-114",icon:"Handshake",accent:"#059669",title:"هاریکاری دگەل بەرگرییا شارستانی",subtitle:"Civil-Military Cooperation (CIMIC)",summary:"هاریکاریا د ناڤبەرا پێشمەرگە و بەرگرییا شارستانی دا (CIMIC)",blocks:[{body:"د کارەساتان دا، پێشمەرگە و بەرگرییا شارستانی پێکڤە کار دکەن."},{heading:"١. ئەرکێن پێشمەرگە",body:"د کارەساتان دا:",points:["لێگەڕیان و ڕزگارکرن.","ئاسایش.","لۆجستیک.","هەوارهاتنا ئێکێ.","پەیوەندی.","ئاڤاکرنەڤە."]},{heading:"٢. هەماهەنگی دگەل بەرگرییا شارستانی (١١٥)",body:"پەیوەندی:",points:["گازی ١١٥ بکە.","کەنالێ پەیوەندیێ یێ هەڤپشک.","سیستەمێ فەرماندەیا ڕووداوێ (ICS).","ناڤەندا ئۆپەراسیۆنێن تەنگاڤیێ (EOC).","ڕاپۆرتا METHANE.","ل ناڤ باژێری، فەرماندەیی یا دەزگەهێن شارستانی یە."]},{heading:"٣. هاریکاریا خەلکی",body:"هاریکاریا مرۆڤانە (Humanitarian Assistance):",points:["خوارن و ئاڤ.","چادر بۆ ئاوارەیان.","کلینیکا میدانی.","ڤەگوهاستنا خەلکی و کەرەستان.","پاراستنا زارۆکان.","ئاگەهدارکرنا خەلکی."]},{heading:"٤. هشیاریا جڤاکی",body:"فێرکرنا خەلکی:",points:["ڕاهێنانێن سەلامەتیێ.","هشیاریا مینان.","قوتابخانە.","کامپەین.","زارۆک: فێرکرنا ساناهی.","ڕادیۆ و تەلەڤزیۆن."]}],media:[{kind:"video",src:"media/videos/mil_cimic.mp4",title:"CIMIC",description:"هاریکاری"}],quiz:[{question:"ل ناڤ باژێری د کارەساتێ دا، فەرماندەیی یا کێیە؟",options:[{text:"هێزێن سەربازی",correct:!1},{text:"بەرگرییا شارستانی",correct:!0},{text:"پۆلیس",correct:!1},{text:"فەرق ناکەت",correct:!1}],explanation:"دەزگەهێن شارستانی (بەرگرییا شارستانی) فەرماندەیێ دکەن و هێزێن سەربازی پشتەڤانیێ دکەن."},{question:"ئەرکێ پێشمەرگە د کارەساتێ دا چ یە؟",options:[{text:"تەنێ پاراستنا بنکەیێن خوە",correct:!1},{text:"دوورکەفتن ژ ناڤچا کارەساتێ و هێلانا وێ بۆ شارستانیان",correct:!1},{text:"وەرگرتنا فەرماندەییا تەمام یا هەمی دەزگەهێن شارستانی، ب بەرگرییا شارستانی ژی ڤە",correct:!1},{text:"ڕزگارکرن، ئاسایش، لۆجستیک و هەوارهاتن، ب هەماهەنگی دگەل ١١٥",correct:!0}],explanation:"پێشمەرگە ب هەماهەنگی دگەل بەرگرییا شارستانی (١١٥) پشتەڤانیێ دکەن: ڕزگارکرن، ئاسایش، لۆجستیک و هەوارهاتن."},{question:"پێشمەرگە د کارەساتێ دا چەوا دگەل بەرگرییا شارستانی هەماهەنگیێ دکەن؟",options:[{text:"ئۆپەراسیۆنەکا جودا دکەن و تەنێ ل دویماهیێ ڕاپۆرتێ ددەن",correct:!1},{text:"گازی ١١٥ دکەن، کەنالێ هەڤپشک بکار دئینن و د ناڤ ICS دا کار دکەن",correct:!0},{text:"ب درێژاهییا کاری تەنێ کەنالێن ڕادیۆیێن سەربازی یێن خوە بکار دئینن",correct:!1},{text:"چاڤەڕێ دکەن هەتا بەرگرییا شارستانی داخوازەکا نڤیسی بۆ هاریکاریێ بهنێریت",correct:!1}],explanation:"هەماهەنگی دگەل بەرگرییا شارستانی ئەڤەیە: گازی ١١٥ بکە، کەنالێ پەیوەندیێ یێ هەڤپشک بکار بینە و د ناڤ سیستەمێ فەرماندەیا ڕووداوێ (ICS) و EOC دا کار بکە؛ ل ناڤ باژێری، فەرماندەیی یا دەزگەهێن شارستانی یە."}]},{id:15,code:"MIL-115",icon:"Megaphone",accent:"#9333ea",title:"هشیارکرن و ئاگەهداریا جڤاکی",subtitle:"Community Safety Education",summary:"ڕۆلێ پێشمەرگە د فێرکرنا خەلکی دا ل سەر سەلامەتیێ و بەرگرییا شارستانی",blocks:[{body:"ئەرکێ پێشمەرگە تەنێ شەڕ نینە. ئاگەهدارکرنا خەلکی ژ مەترسیان ژیانێ ڕزگار دکەت."},{heading:"١. هشیاریا مینان",body:"فێرکرنا خەلکی:",points:["زارۆک: دەست نەدەنێ و بێژنە مەزنان!","جوتیار و ئاڤاکەر: بەری کۆلانێ ژ لایەنێن پەیوەندیدار بپرسن؛ نەبوونا نیشانێن ئاگەهداریێ ب واتایا هندێ نینە کو جه سەلامەتە.","شڤان: پەزی ل ناڤچێن مینان نەچەرینن.","نیشانێن مینان فێربکە، و کو هەرگز نابیت ئەو بهێنە ڕاکرن.","ئەگەر تە مینەک یان تشتەکێ نەناس دیت: نێزیک نەبە، خەلکی ژێ دوور بێخە و ڕاگەهینە؛ د تەنگاڤیێ دا گازی ١١٥ بکە.","ل ناڤچەکا کو بەلکی مین تێدا هەبن: ڕاوەستە، بێ لڤین بمینە و پێیێن خوە نەلڤینە، گازی هاریکاریێ بکە و چاڤەڕێ بە.","وانێن قوتابخانان."]},{heading:"٢. عەردەهەژین",body:"فێرکرن:",points:["خوە بدە عەردی، خوە ڤەشێرە، خوە بگرە (Drop, Cover, Hold On) — ل بن مێزەکا موکم، دوور ژ پەنجەرەیان.","پشکنینا ئاڤاهیان.","جانتایا تەنگاڤیێ: ئاڤ (٤ لیتر بۆ هەر کەسەکی ل ڕۆژێ، بۆ لانیکێم ٣ ڕۆژان).","خالا کۆمبوونێ.","پلانا تەنگاڤیێ یا مالباتێ.","ڕاهێنانێن بەردەوام ل سەر پلانێ."]},{heading:"٣. ئاگر و مال",body:"سەلامەتی:",points:["سۆبا غازێ: هەواگوهۆڕینا باش (مەترسیا غازا CO).","کارەبا: پریزان زێدە بار نەکە.","تەمرینک ل هەر مالەکێ.","ئاگەهدارکەرێ دوکێلێ (Smoke Alarm).","ژمارا ١١٥ ل بیر بیت.","٢ ڕێکێن دەرکەفتنێ."]},{heading:"٤. هەوارهاتنا ئێکێ",body:"بنەما:",points:["فشارا سنگی (CPR): ٣٠:٢، ١٠٠-١٢٠ فشار ل خولەکێ، کویراهی ٥-٦ سم؛ ئەگەر ڕاهێنان نەدیتبی، تەنێ فشارێن سنگی (Hands-Only CPR).","خوینبەربوون: فشارا ڕاستەوخۆ و ب هێز.","شکەستن: نەلڤینە و جێگیر بکە.","سۆتن: ٢٠ خولەکان ئاڤا ڕەوان یا فێنک.","ژەهراویبوون: گازی ١٢٢ بکە و قوتیا ماددێ بپارێزە؛ وی نەدە ڤەڕشاندن و چ خوارن و ڤەخوارنان نەدەیێ.","١١٥ و ١٢٢ ل سەر دیواری بنڤیسە."]},{heading:"٥. ڕێکخستنا کامپەینان",body:"چەوا:",points:["پلان: بابەت + ئارمانج + ناڤچە.","تیم: پێشمەرگە + بەرگرییا شارستانی (١١٥) + ساخلەمی.","جه: قوتابخانە، مزگەفت، گوند.","میدیا: پۆستەر، ڤیدیۆ، تۆڕێن جڤاکی.","گروپێن ئارمانج: زارۆک، ژن، بەرپرس.","هەلسەنگاندن پشتی کامپەینێ."]}],media:[{kind:"video",src:"media/videos/mil_awareness.mp4",title:"هشیاری",description:"فێرکرن"},{kind:"image",src:"media/images/mil_campaign.png",title:"کامپەین",description:"ڕێکخستن"}],quiz:[{question:"ئێکەم وانە بۆ زارۆکان ل سەر مینان چ یە؟",options:[{text:"ب هێدی هەلگرن و بدەنە مەزنان",correct:!1},{text:"دەست نەدەنێ و بێژنە مەزنان!",correct:!0},{text:"ل دویڤ بگەڕێن",correct:!1},{text:"ژ دوور بەردان بهاڤێژنێ",correct:!1}],explanation:"دەست نەدەنێ، دوور بکەڤن و بێژنە مەزنان؛ مەزن گازی ١١٥ دکەن."},{question:"ل هەر مالەکێ، چ ل سەر دیواری بهێتە نڤیسین؟",options:[{text:"ناڤێ خودانێ مالێ",correct:!1},{text:"١١٥ و ١٢٢",correct:!0},{text:"ڕەنگێ دیواری",correct:!1},{text:"چ تشت",correct:!1}],explanation:"ژمارێن تەنگاڤیێ: ١١٥ (بەرگرییا شارستانی) و ١٢٢ (ئەمبوولانس)."},{question:"کامپەینا هشیاریێ ل کیڤە دگەهیتە پترین خەلکی؟",options:[{text:"تەنێ ل ناڤ سەربازخانێ",correct:!1},{text:"ل قوتابخانە، مزگەفت و گوندان",correct:!0},{text:"ل جهەکێ دوور کو کەس لێ نینە",correct:!1},{text:"ب نامەیەکا نهێنی بۆ ئێک کەسی",correct:!1}],explanation:"کامپەین ل جهێن خەلک لێ کۆم دبن (قوتابخانە، مزگەفت، گوند) دگەهیتە پترین کەسان."}]},{id:16,code:"MIL-116",icon:"FireExtinguisher",accent:"#dc2626",title:"تەمرینکا ئاگری — ڕاهێنانا تەمام",subtitle:"Fire Extinguisher — Complete Training (PASS)",summary:"ناسینا هەمی جۆرێن تەمرینکان، پۆلێن ئاگری و ڕێکارا P.A.S.S ب هویری",blocks:[{body:"تەمرینکا ئاگری (Fire Extinguisher) ئامێرەکێ سەرەکییە بۆ ڤەمراندنا ئاگرێن بچویک یێن دەستپێکێ. ل سەربازخانە و بنکەیێن سەربازی، دڤێت هەر پێشمەرگەیەک بشێت ب لەز و دروستی تەمرینکێ بکار بینیت. تەمرینکێن بچووک ب لەز ڤالا دبن، گەلەک جاران د چەند چرکەیان دا، و دەمێ ڤالابوونێ یێ دروست ل سەر لایبلێ هاتییە نڤیسین — ژبەرهندێ دڤێت ب لەز و ب دروستی بهێنە بکارئینان."},{heading:"١. پۆلێن ئاگری ل دویڤ NFPA (Fire Classes)",body:"ل دویڤ سیستەمێ NFPA، ئاگر بۆ ٥ پۆلان دابەش دبیت. پۆلێن ئاگری ل ڤێرێ ب پیتێن NFPA 10 هاتینە نڤیسین وەک ژێدەرێ پرۆژەی؛ سیستەمێ فەرمی یێ دهۆکێ هێشتا نەهاتییە پشتڕاستکرن. بەرامبەرێن EN 2: NFPA A = EN A؛ NFPA B (شلەمەنی) = EN B؛ NFPA B (غاز) = EN C؛ NFPA C (ئامێرێن کارەبێ یێن کارەبا تێدا) چو پۆل د EN دا نینە؛ NFPA D = EN D؛ NFPA K = EN F. پۆلێن ئاگری:",points:["پۆلا A (تشتێن ڕەق): دار، کاغەز، قوماش، چادر. تەمرینک: ئاڤ، تۆزا ABC، کەف.","پۆلا B (شلەمەنی و غازێن ئاگرگر): بەنزین، نەفت، دیزل، ڕۆن. شلەمەنی: CO₂، تۆزا ABC، کەف. غاز: ئێکەم جار غازێ ڕاوەستینە ئەگەر سەلامەت بیت؛ چ جاران ئاگرێ غازێ ڤەنەمرینە ئەگەر نەشێی غازێ ڕاوەستینی. (چ جاران ئاڤێ بکار نەئینە!)","پۆلا C (کارەبا): جەنەراتۆر، پانێل، سویچ. تەمرینک: CO₂، Clean Agent، تۆزا ABC. (ئاڤ و کەفێ بکار نەئینە ئەگەر ل سەر لایبلێ پۆلا C یان نیشانا تاقیکرنا کارەبێ نەبیت، وەک هندەک تەمرینکێن ئاڤا هوور (water mist)!)","پۆلا D (کانزا): مەگنیسیۆم، ئەلەمنیۆم. تەمرینک: تەنێ تەمرینکا Class D یان ماددەیەک یێ کو ناڤێ وی کانزای ل سەر لایبلا وی هاتی، نە ABC. (ئاڤ دبیت تەقینێ چێکەت!)","پۆلا K (مەتبەخ): ڕۆنێن مەتبەخێ. تەمرینک: Wet Chemical، نە ABC. (ئاڤ ڕۆنا داخ بەلاڤ دکەت!)"]},{heading:"٢. جۆرێن تەمرینکان",body:"ڕەنگ نە پۆلا ئاگری یە. ل دویڤ ستاندەردێ ئەورووپی BS EN 3، لەشێ تەمرینکێ سۆرە؛ ل بەریتانیا پارچەیەکا ڕەنگکری (BS 7863) ماددێ نیشان ددەت. وەلاتێن دی ڕەنگێن دی بکار دئینن و ڕەنگێن د دهۆکێ دا هێشتا نەهاتینە پشتڕاستکرن، لەوا هەمیشە لایبلێ و نیشانێن پۆلێ بخوینە. پۆلێن خوارێ ب پیتێن NFPA نە:",points:["تەمرینکا ئاڤێ (Water): تەمام سۆر، بێ پارچەیا ڕەنگکری — تەنێ بۆ پۆلا A.","تەمرینکا CO₂: پارچەیا ڕەش — بۆ پۆلا B و ئامێرێن کارەبێ یێن کارەبا تێدا (B و C ل دویڤ NFPA؛ ل دویڤ EN 2، C غازە و CO₂ بۆ ئاگرێن غازێ نینە). دووراهیا وێ کێمە و نە بۆ ئاگرێن کویر یێن دار و کاغەزی یە. تەنێ دەسکی بگرە، چ جاران دەست نەدە لۆلێ: گەلەک سار دبیت و دەستی دقەرسینیت! د ژوورەکا بچووک دا پشتی بکارئینانێ دەرکەڤە و هەوای بگوهۆڕە، چونکی CO₂ ئۆکسجینێ دەردئێخیت.","تەمرینکا تۆزا ABC (Dry Powder): پارچەیا شین — بۆ پۆلا A، B، C؛ نە بۆ D و K. بەربەلاڤترین جۆرە.","تەمرینکا کەفێ (Foam): پارچەیا کرێمی — بۆ پۆلا A و B. بۆ کارەبێ بکار نەئینە!","تەمرینکا Clean Agent: پۆلێن وێ ل دویڤ مۆدێلێ جودانە، لەوا لایبلێ بخوینە (گەلەک جاران B و C ب پیتێن NFPA) — بۆ ئامێرێن هەستیار.","تەمرینکا Wet Chemical: پارچەیا زەرد — بۆ پۆلا K (NFPA K = EN F). تەمرینکا Class D: دڤێت ناڤێ وی کانزایێ ل وێرێ بکار دهێت ل سەر لایبلا وێ هاتبیت."]},{heading:"٣. ڕێکارا P.A.S.S",body:"بەری تو تەمرینکێ بکار بینی (دڤێت هەمی بەرسڤ «بەلێ» بن): ئاگر بچووک و تازە دەستپێکری بیت، وەک ئاگرەکێ د سەتلەکا زبلی دا؛ تەمرینک گونجای بیت؛ ڕێکا دەرکەفتنێ ل پشت تە بیت؛ ئاگەهداری هاتبیتە دان و گازی ١١٥ هاتبیتە کرن؛ تو ڕاهێنان دیتی بی؛ چو دوکێل یان گەرمی ڕێکا تە نەگریت. ئەگەر ئاگر ئێکسەر ڤەنەمری، تەمرینک ڤالا بوو یان دوکێل و گەرمی زێدە بوون، ڕاوەستە، دەرکەڤە و دەرگەهی بگرە. ژیان بەری مال و کەلوپەلان دهێت. P.A.S.S ڕێکارا گشتی یە بۆ پتریا تەمرینکێن دەستی؛ تەمرینکێن Class D، Wet Chemical، Clean Agent و یێن ل سەر چەرخان: ل دویڤ لایبلێ و ڕێنمایێن کۆمپانیا دروستکەر بکار بینە:",points:["P = Pull (بکێشە): مێخا سەلامەتیێ بکێشە.","A = Aim (ئاراستە بکە): لۆلێ بەرەڤ بنێ ئاگری بکە — نە بەرەڤ گڕێ!","S = Squeeze (فشار بدە): دەسکێن تەمرینکێ ب هێز فشار بدە.","S = Sweep (بلڤینە): لۆلێ ب چەپ و ڕاست بلڤینە هەتا ئاگر ڤەدمریت."]},{heading:"٤. پشکنینا هەیڤانە یا تەمرینکان",body:"هەر هەیڤەکێ ب چاڤان بپشکنە (NFPA 10):",points:["فشارا ناڤ تەمرینکێ: ئەگەر پیڤەرا فشارێ هەبیت، دڤێت مێلکا وێ ل ناڤ ئاستێ کەسک بیت. تەمرینکێن CO₂ پیڤەرا فشارێ نینە: هەلگرە دا هەست بکەی کو تژی یە.","مێخا سەلامەتیێ و مۆرا وێ: ل جهێ خوە بن.","لۆلە: نابیت شکەستی یان گرتی بیت.","لەشێ تەمرینکێ: نابیت ژەنگی یان زیانڤێکەفتی بیت.","ئەڤان ژێک جودا بکە: پشکنین و چاککرنا سالانە ژ لایێ کەسەکێ شارەزا ڤە؛ تژیکرنەڤە (Recharge) پشتی هەر بکارئینانەکێ، هەتا ئەگەر کورت ژی بیت؛ هەر ٦ سالان، تەمرینکێن تۆزا هشک یێن فشارا هەلگرتی (stored-pressure) یێن کو پێدڤی ب تاقیکرنا هایدرۆستاتیک یا ١٢ سالان هەی ڤالا دکەن و ناڤا وان دپشکنن؛ تاقیکرنا هایدرۆستاتیک (تاقیکرنا فشارێ یا لەشێ وێ) هەر ٥ سالان بۆ تەمرینکێن ئاڤێ، کەفێ، CO₂ و تۆزا هشک یا ستێنلێس ستیل (stainless steel)، و هەر ١٢ سالان بۆ تەمرینکێن تۆزا هشک یێن فشارا هەلگرتی یێن لەشێ وان ژ ئاسنێ نەرم (mild steel)، مسێ زەرد یێ لحیمکری (brazed brass) یان ئەلەمنیۆمێ. تاقیکرن نە گوهۆڕینە. ڕێسایێن دهۆکێ هێشتا نەهاتینە پشتڕاستکرن."]},{heading:"٥. مەترسیێن تایبەت ل بنکەیێن سەربازی",body:"بنکەیێن سەربازی جهێن هەستیارن:",points:["سۆتەمەنی و بەنزین: کۆگەها سۆتەمەنیێ — پۆلا B.","جەبەخانە و تەقەمەنی: مەترسیا تەقینێ — ئاگری ڤەنەمرینە! هەتا وێ دووراهیێ دوور بکەڤە یا کو ڕێسایێن سەلامەتیا تەقەمەنیێ یێن فەرماندەیا تە بۆ وی جهی دیار دکەن، ناڤچێ ببەستە و گازی ١١٥ بکە. دووراهیا ERG Guide 112، ١٦٠٠ مەتر (١ میل) ل هەمی ئالیان، بۆ تەقەمەنیێن د ڤەگوهاستنێ دا یە (ترمبێلەکا کو تەقەمەنی تێدا هەبن د ئاگری دا، یان گەهشتنا ئاگری بۆ بارێ تەقەمەنیێ).","جەنەراتۆر و کارەبا: پۆلا C — CO₂، Clean Agent یان تۆزا ABC؛ ئەگەر بشێی، ئێکەم کارەبێ ببڕە.","چادر و کۆنتەینەر: ماددەیێن هشک — پۆلا A.","تەمرینکان نێزیکی دەرگەهان دانە؛ دووراهیا گەهشتنێ بۆ تەمرینکەکێ ژ ٢٣ مەتران پتر نەبیت بۆ پۆلا A، و ٩-١٥ مەتر بۆ پۆلا B (NFPA 10)."]}],media:[{kind:"video",src:"media/videos/mil_fire_ext.mp4",title:"تەمرینکا ئاگری",description:"ڕێکارا P.A.S.S بۆ پێشمەرگە"}],quiz:[{question:"ب پیتێن NFPA، تەمرینکا CO₂ بۆ کیژ پۆلێن ئاگری گونجایە؟",options:[{text:"A و D",correct:!1},{text:"B و C",correct:!0},{text:"A و K",correct:!1},{text:"D و K",correct:!1}],explanation:"CO₂ بۆ شلەمەنیێن ئاگرگر (B) و ئامێرێن کارەبێ (C) گونجایە. ل دویڤ EN 2، C ئاگرێن غازێ نە و CO₂ بۆ وان نینە."},{question:"ل ڕێکارا P.A.S.S، لۆلا تەمرینکێ دڤێت بەرەڤ کیڤە بیت؟",options:[{text:"سەرێ گڕێ",correct:!1},{text:"بنێ ئاگری",correct:!0},{text:"دوور ژ ئاگری",correct:!1},{text:"بانێ ژوورێ",correct:!1}],explanation:"هەمیشە لۆلێ بەرەڤ بنێ ئاگری بکە."},{question:"بۆچی ئاڤ ل سەر ئاگرێ ڕۆنی (پۆلا K) ناهێتە ڕێژتن؟",options:[{text:"تەنێ مەنجەلێ سار دکەت و ناگەهیتە ئاگری",correct:!1},{text:"ئاڤ ڕۆنا داخ بەلاڤ دکەت و تەقینێ چێدکەت",correct:!0},{text:"ڕۆن ئاڤێ دخۆت",correct:!1},{text:"ئاڤ دگەل ڕۆنا داخ تێکەل دبیت و دبیتە غازەکا ژەهری",correct:!1}],explanation:"ئاڤ ل سەر ڕۆنا داخ ب لەز دبیتە هەلم و ڕۆنا سۆژ بەلاڤ دکەت (Flash Fire)."}]},{id:17,code:"MIL-117",icon:"Heart",accent:"#db2777",title:"هەوارهاتنا ئێکێ و CPR",subtitle:"First Aid & CPR — Complete Training",summary:"ڕاهێنانا تەمام ل سەر هەوارهاتنا ئێکێ، فشارا سنگی (CPR) و هەلسوکەفتا تەنگاڤیێ ل بنکەیێن سەربازی",blocks:[{body:"هەوارهاتنا ئێکێ (First Aid) ئەو هاریکاریا دەستپێکێ یە کو بەری هاتنا تیمێن پزیشکی دهێتە دان بۆ کەسێ بریندار یان نەخۆش. ل بنکەیێن سەربازی، مەترسیا برینداربوونێ گەلەک بلندە — ژ برینێن شەڕ و تەقینان هەتا شۆکا کارەبێ و کەفتنێ. دڤێت هەر پێشمەرگەیەک بزانیت چەوا CPR بکەت، خوینبەربوونێ ڕاوەستینیت، و بریندارێ هەتا هاتنا ئەمبوولانسێ (١٢٢) بپارێزیت."},{heading:"١. CPR — ڤەژاندنا دل و سییان (ب هویری)",body:"CPR ڕێکارەکا ڕزگارکرنا ژیانێ یە دەمێ دلێ مرۆڤی یان هەناسەدانا وی ڕادوەستیت:",points:["١. سەلامەتیا جهی: پشتڕاست بە کا جهێ برینداری سەلامەتە (تەقەمەنی، ئاگر، غاز نینن؟).","٢. بەرسڤدان: ل سەر ملێن وی بدە و ب دەنگێ بلند بپرسە: «تو باشی؟ دەنگێ من دبهیسی؟»","٣. گازی ١٢٢: ئەگەر بەرسڤ نەدا و ب ئاسایی هەناسە نەدا (ژ ١٠ چرکەیان کێمتر بپشکنە)، ئێکسەر گازی ١٢٢ بکە و AED بینە.","٤. فشارێن سنگی (Compressions): ٣٠ فشار ل ناڤەڕاستا سنگی — کویراهی: ٥-٦ سم، لەز: ١٠٠-١٢٠ فشار ل خولەکێ.","٥. هەناسەدان: سەری پاشڤە ببە و چەنێ بلند بکە، دفنێ بگرە، ٢ هەناسێن ١ چرکەیی بدە. ئەگەر ڕاهێنان نەدیتبی یان نەڤێی هەناسان بدەی، تەنێ فشارێن سنگی بدە (Hands-Only CPR)، بێ ڕاوەستان.","٦. بەردەوامی (٣٠ ب ٢): هەتا ئەمبوولانس (١٢٢) دگەهیت یان بریندار ب ئاسایی هەناسێ ددەت.","٧. AED: ئێکسەر کو گەهشت، ڤەکە، لەزگەیان بلکینە سەر سنگی و ل دویڤ دەنگێ ئامێری بچە."]},{heading:"٢. کۆنترۆلکرنا خوینبەربوونێ",body:"خوینبەربوونا توند دشێت د دەمەکێ کێم دا مرۆڤی بکوژیت:",points:["فشارا ڕاستەوخۆ: پەڕۆیەکێ پاقژ بدە سەر برینێ و ب هێز فشار بدە. ئەگەر پەڕۆ ب خوینێ تێر بوو، لانەبە — پەڕۆیەکێ دی بدە سەر.","پڕکرنا برینێ (Wound Packing): بۆ برینێن کویر ل ستوی، بن چەنگی یان ناڤ ڕانێ، برینێ ب گازێ پڕ بکە و فشار بدە.","تۆرنیکێت (Tourniquet): بۆ خوینبەربوونا مەترسیدار ژ دەست یان لنگی زوو بکار بینە — ٥-٧ سم سەرتر ژ برینێ؛ دەمێ بنڤیسە و چ جاران شل نەکە.","تشتێ چەقی: ئەگەر ئاسن، شووشە یان پارچەیێن تەقینێ ل ناڤ برینێ بن — دەرنەکێشە! دەوروبەرێ وی جێگیر بکە."]},{heading:"٣. چارەسەرکرنا سۆتنێ",body:"سۆتن ل میدانێ و بنکەیان:",points:["سۆتنا گەرمیێ: ٢٠ خولەکان ئاڤا ڕەوان یا فێنک بڕێژە سەر جهێ سۆتی (نە قەشا).","سۆتنا کیمیایی: تۆزا هشک ئێکەم ب نەرمی لابە، پاشان ب ئاڤەکا گەلەک ٢٠ خولەکان بشۆ.","سۆتنا کارەبێ: ئێکەم کارەبێ ببڕە! پاشان وەک سۆتنا گەرمیێ، و گازی ١٢٢ بکە.","بلقێن سۆتنێ نەتەقینە؛ دۆهن، کرێم و مەعجوونا ددانان بکار نەئینە."]},{heading:"٤. شکەستن و برینێن پشتێ",body:"ل دەمێ کەفتنێ:",points:["جێگیرکرن (Splinting): ئەندامێ بریندار نەلڤینە — ب دارەکێ جێگیر بکە.","پاراستنا پشتێ: ئەگەر کەسەک ژ بلندیێ کەفت، نەلڤینە؛ بێ لڤین بهێلە و گازی ١٢٢ بکە. تەنێ ئەگەر جه مەترسیدار بیت (ئاگر، ترافیک، هەرفتن، غاز، بلندبوونا ئاڤێ) وی بلڤینە، و سەر، ستوی و پشتا وی ل سەر ئێک هێلێ بهێلە. ئەگەر پێدڤی ب CPR هەبیت، وی ل سەر پشتێ ل سەر ڕووبەرەکێ ڕەق درێژ بکە. وی ل سەر تەنشتێ (Recovery Position) دانەنە.","سارکرن: قەشایێ د پەڕۆیەکێ دا بپێچە و بدە سەر جهێ ئێشانێ (نە ڕاستەوخۆ ل سەر پێستی)."]},{heading:"٥. شۆکا کارەبێ و ڕزگارکرن",body:"کارەبا دشێت دلی ڕاوەستینیت:",points:["ئێکسەر کارەبێ ببڕە! هەتا کارەبا نەهاتبیتە بڕین، دەست ل برینداری نەدە.","ئەگەر نەشیای ببڕی و کارەبا نزم بیت: ب دارەکێ هشک یان پلاستیکی وایەری ژ برینداری جودا بکە. ل کارەبا بلند نێزیک نەبە و گازی ١١٥ بکە.","هەمی کەسێن کارەبێ لێ دای دڤێت بچنە نەخۆشخانێ (١٢٢)."]}],media:[{kind:"video",src:"media/videos/mil_cpr.mp4",title:"CPR و هەوارهاتنا ئێکێ",description:"ڕاهێنانا CPR بۆ پێشمەرگە"}],quiz:[{question:"د ڕێکارا CPR دا، چەند فشارێن سنگی ل خولەکێ دڤێت بهێنە دان؟",options:[{text:"٥٠-٧٠",correct:!1},{text:"٨٠-٩٠",correct:!1},{text:"١٠٠-١٢٠",correct:!0},{text:"١٣٠-١٦٠",correct:!1}],explanation:"١٠٠-١٢٠ فشار ل خولەکێ."},{question:"ئەگەر تشتەکێ تیژ د ناڤ برینێ دا چەقی بوو، دێ چ کەی؟",options:[{text:"دەردکێشم",correct:!1},{text:"ل جهێ وی دهێلم و گازی ١٢٢ دکەم",correct:!0},{text:"دەست لێ نادەم و برینداری دهێلم و دچم",correct:!1},{text:"ب ئاڤێ دشۆم و دەردکێشم",correct:!1}],explanation:"دەرکێشانا تشتی دێ خوینبەربوونێ زێدەتر کەت؛ دەوروبەرێ وی جێگیر بکە و گازی ١٢٢ بکە."},{question:"ئەگەر کارەبێ ل کەسەکی دابیت، ئێکەم کار چ یە؟",options:[{text:"دەستێ وی دگرم",correct:!1},{text:"CPR دکەم",correct:!1},{text:"کارەبێ دبڕم",correct:!0},{text:"ئاڤێ دڕێژمە سەر",correct:!1}],explanation:"دڤێت ئێکەم جار کارەبا بهێتە بڕین."}]}],t={lessons:e};export{t as default,e as lessons};
